      rewardGoldSoft:"rgba(200,144,26,0.14)",
      her:"#D6497E", herSoft:"#FBE4EE", him:"#3E86C4", himSoft:"#E1EEF8",
      urgent:"#E23E5C", urgentSoft:"#FBE1E6", medium:"#E0913A", mediumSoft:"#FBEEDA",
