const THEME_ORDER = ["sleek","bold"];
const DEFAULT_THEME = "sleek";

// Relative luminance of a hex colour (0 dark → 1 light). Used to pick readable
// on-accent text (black vs white).
function hexLum(hex){
  const h=hex.replace('#','');
  const r=parseInt(h.slice(0,2),16)/255, g=parseInt(h.slice(2,4),16)/255, b=parseInt(h.slice(4,6),16)/255;
  const f=c=>c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4);
  return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b);
}
// Shift a hex's hue by `deg`, optionally nudging lightness — for the gradient partner.
function shiftHue(hex,deg,dl=0){
  const h=hex.replace('#','');
  let r=parseInt(h.slice(0,2),16)/255,g=parseInt(h.slice(2,4),16)/255,b=parseInt(h.slice(4,6),16)/255;
  const max=Math.max(r,g,b),min=Math.min(r,g,b);let hh,s,l=(max+min)/2;
  if(max===min){hh=s=0;}else{const d=max-min;s=l>0.5?d/(2-max-min):d/(max+min);
    hh=max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4;hh/=6;}
  hh=(hh*360+deg+360)%360; l=Math.max(0,Math.min(1,l+dl));
  return hslToHex(hh,Math.round(s*100),Math.round(l*100));
}
// Extract the hue (0–360) from a hex colour — used to seed the spectrum slider.
function hexHue(hex){
  const h=hex.replace('#','');
  let r=parseInt(h.slice(0,2),16)/255,g=parseInt(h.slice(2,4),16)/255,b=parseInt(h.slice(4,6),16)/255;
  const max=Math.max(r,g,b),min=Math.min(r,g,b);
  if(max===min) return 0;
  const d=max-min;
  let hh=max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4;
  return Math.round((hh/6)*360);
}
// Lightness (0–100) from a hex — used to seed the spectrum's light↔dark slider.
function hexLight(hex){
  const h=hex.replace('#','');
  let r=parseInt(h.slice(0,2),16)/255,g=parseInt(h.slice(2,4),16)/255,b=parseInt(h.slice(4,6),16)/255;
  const max=Math.max(r,g,b),min=Math.min(r,g,b);
  return Math.round(((max+min)/2)*100);
}
// Saturation (0–100) from a hex — the spectrum picker had NO saturation control at all, so
// every colour it produced was pinned at S=72. That's why sage, sand, dusty rose, charcoal
// and grey were all unreachable: they aren't dark or light versions of a vivid colour, they
// are LESS SATURATED ones.
function hexSat(hex){
  const h=hex.replace('#','');
  const r=parseInt(h.slice(0,2),16)/255,g=parseInt(h.slice(2,4),16)/255,b=parseInt(h.slice(4,6),16)/255;
  const max=Math.max(r,g,b),min=Math.min(r,g,b);
  if(max===min) return 0;                 // a grey — no hue to saturate
  const l=(max+min)/2, d=max-min;
  return Math.round((l>0.5 ? d/(2-max-min) : d/(max+min))*100);
}
// Readable ink for a chip whose background is softTint(hex) — a TRANSLUCENT wash, so the
// real background is that wash composited over the page, and the page differs by mood.
//
// The first attempt judged contrast against the raw colour and produced 1.15:1 in places —
// unreadable. The colour is NOT the background; the tint over the page is. So composite it
// first, then pick an ink that actually contrasts with THAT.
//
// Opening the picker to L 8–92 is what made this necessary: at the old S72/L25–80 the raw
// colour happened to contrast with its own pale tint. A pale mint or a charcoal does not.
function readableInk(hex, tintAmt=0.16){
  const h=hex.replace('#','');
  const r=parseInt(h.slice(0,2),16), g=parseInt(h.slice(2,4),16), b=parseInt(h.slice(4,6),16);
  // The chip's ACTUAL background: the colour at `tintAmt` opacity over the page.
  const pg=(C.page||"#FFFFFF").replace('#','');
  const pr=parseInt(pg.slice(0,2),16), pgr=parseInt(pg.slice(2,4),16), pb=parseInt(pg.slice(4,6),16);
  const br=r*tintAmt+pr*(1-tintAmt), bg=g*tintAmt+pgr*(1-tintAmt), bb=b*tintAmt+pb*(1-tintAmt);
  const rel=c=>{c/=255; return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4);};
  const bgLum=0.2126*rel(br)+0.7152*rel(bg)+0.0722*rel(bb);
  // Darken or lighten THE CATEGORY COLOUR until it clears the background — keeping the hue,
  // so a pale sage still reads as sage rather than as generic black text. Step until it
  // passes 4.5:1 rather than guessing a fixed amount, because how far you must go depends
  // on the hue (a yellow starts far brighter than a blue).
  const target=bgLum>0.35?"#000000":"#FFFFFF";
  for(let t=0.15;t<=0.95;t+=0.1){
    const cand=mixHex(hex,target,t);
    const m=/(\d+)[,\s]+(\d+)[,\s]+(\d+)/.exec(cand);
    if(!m) break;
    const cl=0.2126*rel(+m[1])+0.7152*rel(+m[2])+0.0722*rel(+m[3]);
    const [hi,lo]=[cl,bgLum].sort((x,y)=>y-x);
    if((hi+0.05)/(lo+0.05)>=4.5) return cand;
  }
  return target;   // the hue simply can't clear it — fall back to plain black/white
}
// From one accent hex + mood, derive the full accent family so every dependent
// token (gradient, glow, soft fills, on-accent text) stays coherent.
function deriveAccent(hex,mood){
  const accent2=shiftHue(hex, mood==="sleek"? -18 : 12, mood==="sleek"?0.02:-0.04);
  const deep=shiftHue(hex,0,-0.12);
  const onAccent=hexLum(hex)>0.55?"#0F1117":"#FFFFFF";
  const soft = mood==="sleek" ? rgbaFromHex(hex,0.14) : mixHex(hex,"#FFFFFF",0.82).replace("rgb","rgb");
  return {
    heroTop:hex, heroBot:accent2, heroGlow:rgbaFromHex(hex,mood==="sleek"?0.22:0.18),
    accent:hex, accent2, accentDeep:deep, accentSoft:soft,
    onAccent, glow: mood==="sleek"?`0 0 14px ${rgbaFromHex(hex,0.55)}`:"none",
    low:hex, lowSoft:soft,
  };
}
const ACCENT_PRESETS = {
  sleek:["#5EE7B4","#4AD0E0","#6C8AE0","#A78BFA","#F472B6","#FBBF24"],
  bold:["#E0663A","#E23E5C","#2E7FE0","#7C5CE0","#1FA97A","#E0913A"],
};
const DEFAULT_ACCENT = { sleek:"#5EE7B4", bold:"#E0663A" };

// Live token object — mutated in place so existing C.xxx references stay valid.
const C = { ...THEMES[DEFAULT_THEME].tokens };
// Custom accents (per mood) layered over the base theme when applied.
let CUSTOM_ACCENT = { sleek:null, bold:null };
// ── ADJUSTABLE BACKGROUND *(v290)* ────────────────────────────────────────────
// One slider per mood, 0..1 along a ramp. Mandy wanted Bold to be able to go pure
// white; Sleek gets the same control from deep grey through to black.
//
// THE WHOLE DIFFICULTY IS THE CARD. In Bold, cards are ALREADY #FFFFFF sitting on a
// cream page — that is what makes them read as raised. Take the page to white and the
// separation falls from 1.077 to 1.000 and cards vanish into the background. So the
// page is the only thing chosen; `card` is DERIVED from it and always kept clear of it.
//   · dark mood  → card is the page lifted toward white
//   · light mood → card is white UNTIL the page is nearly white, then it steps down
// Measured across both ramps the separation never drops below the current default
// (bold 1.076 vs 1.077, sleek 1.088 vs 1.085) — pinned by probe-bg.
// The ramp is TWO segments hinged on the SHIPPED colour, not a straight line between the
// extremes. A straight line does not pass through #FBF6EC or #0F1117 — the channels
// disagree by up to 0.134 — so the slider's default position would render a colour close
// to, but not the same as, the app's own default. Reset would then restore the theme while
// the slider sat somewhere that draws something else: a control lying about where it is.
// Hinging guarantees def reproduces the shipped page EXACTLY.
const BG_RAMP={
  sleek:{ from:"#242833", mid:"#0F1117", to:"#000000", def:0.5 },   // deep grey → shipped → black
  bold :{ from:"#FFFFFF", mid:"#FBF6EC", to:"#F2E9D4", def:0.5 },   // white → shipped → deeper cream
};
const CUSTOM_BG={ sleek:null, bold:null };
function setCustomBg(mood,v){ CUSTOM_BG[mood]= (v==null?null:Math.max(0,Math.min(1,Number(v)))); }
// Relative luminance, for deciding which way a card must move.
function hexLum2(h){
  const p=String(h||"").replace("#","");
  const q=p.length===3?p[0]+p[0]+p[1]+p[1]+p[2]+p[2]:p;
  const v=[0,2,4].map(i=>parseInt(q.slice(i,i+2),16)/255)
    .map(c=>c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4));
  return 0.2126*v[0]+0.7152*v[1]+0.0722*v[2];
}
function hexMix(a,b,t){
  const p=h=>{const x=String(h||"").replace("#","");
    const y=x.length===3?x[0]+x[0]+x[1]+x[1]+x[2]+x[2]:x;
    return [0,2,4].map(i=>parseInt(y.slice(i,i+2),16));};
  const A=p(a),B=p(b);
  return "#"+[0,1,2].map(i=>Math.round(A[i]+(B[i]-A[i])*t).toString(16).padStart(2,"0")).join("").toUpperCase();
}
// The full background set for a mood at slider position v.
function deriveBg(mood,v){
  const r=BG_RAMP[mood]||BG_RAMP.sleek;
  // CLAMP HERE, not only in the setter. A value out of range produces nonsense like
  // "#14016D1D6" — an invalid colour that CSS drops silently, so the page would render
  // with NO background at all. localStorage is the untrusted path: a hand-edited or
  // half-written value must not be able to blank the app.
  const t=Math.max(0,Math.min(1, Number(v)||0));
  // Two segments: 0..0.5 walks from `from` to the shipped `mid`, 0.5..1 from `mid` to
  // `to`. At exactly 0.5 the page IS the shipped colour, so the slider's rest position
  // and the app's default are the same thing.
  const page = t<=0.5 ? hexMix(r.from,r.mid,t/0.5) : hexMix(r.mid,r.to,(t-0.5)/0.5);
  const dark=mood==="sleek";
  // A card must never match its page. On light, once the page passes ~0.92 luminance
  // there is no headroom above it, so the card steps DOWN instead of up.
  // THE LIFT SCALES WITH HEADROOM. A FIXED lift cannot do both jobs: 0.0395 reproduces
  // Sleek's shipped card at the hinge but collapses to 1.06 separation at pure black,
  // below the 1.085 floor. Near black there is almost no luminance to work with, so the
  // lift has to grow. Interpolating from 0.0395 at the hinge to 0.075 at the extremes
  // keeps the default faithful AND the whole ramp above the floor.
  const away = Math.abs(t-0.5)*2;                  // 0 at the hinge → 1 at either end
  const lift = 0.0395 + 0.0355*away;
  // LIGHT MOOD: SOLVE FOR A CONSTANT CONTRAST RATIO, not a constant mix amount.
  //
  // Two earlier attempts failed and the probe caught both. A hard luminance threshold
  // made the card jump from grey to white in one notch, 1.059 apart at the crossing. A
  // smooth blend keyed on "how near white" left the card pure white against an almost
  // white page just below the hinge — 1.006, effectively invisible.
  //
  // The quantity that must stay constant is the RATIO itself, so it is solved for
  // directly. From the hinge upward (cream and deeper) white is available and is what
  // ships, so the card is simply white.
  const card = dark ? hexMix(page,"#FFFFFF",lift)
                    : (t>=0.5 ? "#FFFFFF" : (()=>{
                        // Bisect the mix toward a neutral dark until the page/card
                        // ratio reaches 1.09 — comfortably above the 1.077 default.
                        let lo=0, hi=0.25;
                        for(let i=0;i<24;i++){
                          const m=(lo+hi)/2;
                          const c=hexMix(page,"#2E2E36",m);
                          const l1=hexLum2(page), l2=hexLum2(c);
                          const rr=(Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);
                          if(rr<1.09) lo=m; else hi=m;
                        }
                        return hexMix(page,"#2E2E36",(lo+hi)/2);
                      })());
  // pageWarm is inputs and inset panels. It has to travel with the page or fields
  // float at the old tone against a moved background.
  const pageWarm = dark ? hexMix(page,"#FFFFFF",0.03) : hexMix(page,"#000000",0.02);
  // cardRaise sits above card (menus, raised sheets) — same direction as card.
  const cardRaise = dark ? hexMix(card,"#FFFFFF",0.03) : hexMix(card,"#000000",0.015);
  return {page,pageWarm,card,cardRaise};
}
function applyTheme(key){
  const t = THEMES[key] || THEMES[DEFAULT_THEME];
  Object.keys(C).forEach(k=>{ delete C[k]; });
  Object.assign(C, t.tokens);
  const custom = CUSTOM_ACCENT[key];
  if(custom){ Object.assign(C, deriveAccent(custom, t.tokens.mood)); }
  // AFTER the accent, so a derived accent can never overwrite the chosen background.
  const bg = CUSTOM_BG[key];
  if(bg!=null){ Object.assign(C, deriveBg(t.tokens.mood, bg)); }
}
function setCustomAccent(mood,hex){ CUSTOM_ACCENT[mood]=hex; }

// Blend two hex colours (t=0→a, 1→b). Used for gradient midpoints.
// Accepts 3- OR 6-digit hex. The 3-digit case is NOT cosmetic: "#000" was being
// passed at several call sites (bill tiles, the Bills header, event gradients),
// and slice(4,6) on "000" is "" → parseInt("") → NaN → "rgb(66,162,NaN)", an
// invalid CSS colour, so the gradient's second stop silently didn't render.
function mixHex(a,b,t){
  const p=h=>{
    h=String(h||"").replace('#','');
    if(h.length===3) h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];   // #000 → #000000
    return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];
  };
  const [r1,g1,b1]=p(a),[r2,g2,b2]=p(b);
  const m=(x,y)=>Math.round(x+(y-x)*t);
  return `rgb(${m(r1,r2)},${m(g1,g2)},${m(b1,b2)})`;
}

// Derive a soft pill fill from any hex. In the light (Bold) mood we tint toward
// white; in the dark (Sleek) mood we return a low-alpha wash so pills read on
// dark cards. Mood is taken from the live C.mood token.
function softTint(hex, amt=0.86){
  const h = hex.replace("#","");
  const r = parseInt(h.slice(0,2),16), g = parseInt(h.slice(2,4),16), b = parseInt(h.slice(4,6),16);
  if(C.mood==="sleek"){ return `rgba(${r},${g},${b},0.16)`; }
  const mix = (c)=>Math.round(c + (255-c)*amt);
  return `rgb(${mix(r)},${mix(g)},${mix(b)})`;
}

// ─── v207 · OPAQUE TINT — FOR ANYTHING DRAWN ON A SHEET ──────────────────────
// softTint() returns rgba(r,g,b,0.16) in SLEEK mood. On a CARD that is correct and
// deliberate: the page shows through by 84% and the tint reads as a wash.
//
// On a SHEET it is a bug. A dialog floats above the page, so a 16%-opaque row lets the
// whole page read straight through it — Mandy photographed "Feed Leo" legible through
// "Delete the whole series" in the delete-scope prompt, on a Samsung S25 Ultra.
//
// The fix is NOT to change softTint: it has ~190 call sites and the translucency is
// right at nearly all of them. Instead, anything sitting ON A SHEET composites the same
// colour to an OPAQUE value against the surface it is drawn on. The result is visually
// identical over a solid surface — it just cannot be seen through.
//
// BOLD mood is unaffected either way: softTint already returns an opaque rgb() there.
// This helper is therefore a no-op in Bold, which is why it must be tested in BOTH moods.
function solidTint(hex, surface, amt=0.16){
  // mixHex returns an opaque rgb(); mixing the tint colour INTO the surface by the same
  // fraction softTint would have used as alpha reproduces the composited result exactly.
  return mixHex(surface || C.card, hex, C.mood==="sleek" ? amt : 0.14);
}

// Glow — a module-level flag mirrored from React state (GLOW.on) so any
// component reading module-scope C can also honour the glow setting.
const GLOW = { on:false };
// ─── SHEET DEPTH LADDER *(v198)* ─────────────────────────────────────────────
// Sheets are SIBLINGS at App level, so z-index alone decides which is on top. Every
// sheet used to hardcode its own number; the values had spread across TWELVE different
// combinations from 200 to 340 with no system, and four RECORD EDITORS ended up at 200
// — BELOW DaySheet (210), the very sheet that opens them. Tapping a Day-off card in the
// day sheet opened the editor BEHIND it (and under a second scrim), while tapping a
// Shift card worked, because ShiftModal happened to be at 250.
//
// The rungs, lowest to highest:
//   Z_ACTIONS  205 — day-actions chooser
//   Z_SHEET    210 — container sheets (day sheet, planner, rota)
//   Z_PANEL    220 — person/settings/bonus panels opened from a tab
//   Z_EDITOR   250 — ANY editor that edits ONE record. MUST outrank Z_SHEET, because
//                    every one of them is opened FROM a container sheet.
//   Z_CONFIRM  270 — confirms and scope prompts, which interrupt an editor
// Rule: a sheet opened FROM another sheet must sit on a HIGHER rung. New editors read
// Z_EDITOR — never a literal.
const Z_ACTIONS=205, Z_SHEET=210, Z_PANEL=220, Z_EDITOR=250, Z_CONFIRM=270;
// v279 · The card-details sheet opens FROM the task editor, so it must sit above it.
const Z_CARDTERMS=280;
// v236 · The ONE dimmer value. Individual overlays no longer choose their own darkness:
// only the first scrim paints (see .hb-scrim in the global CSS), so a per-sheet value was
// never anything but the depth at which that particular sheet happened to be opened first.
// DayNoteSheet also sat at zIndex 80 — BELOW the entire ladder, and below the DaySheet it
// opens from. It rendered on top only because it is mounted as a later sibling, which is
// luck, not order. It now reads Z_EDITOR like every other single-record editor.
const SCRIM_DIM = "rgba(0,0,0,0.62)";
// Points visibility — module-level mirror of the "Show points" setting so any
// component reading module-scope can hide all point-driven UI when it's off.
const PTS = { on:true };
// Mirrored settings that cross-cutting components read directly, rather than being
// threaded through five layers of props. Same pattern as PTS.
// keypad  — autofocus the amount field when ticking a bill paid
// editPaid — may a COMPLETED record be rewritten? Governs the bill "Correct this payment"
//            panel and the task done-date sheet together. Replaced CAN_EDIT_DONE in v119.
const BILLUI = { keypad:true, editPaid:true };
// Shared-assignee display — module-level mirror of the "Name shared tasks"
// setting. When on, a "both" item renders a badge per person instead of a
// single "Both" chip. Presentational only; the stored assignee stays "both".
const SHARED = { named:false };
// Card-title font — module-level mirror of the "Card heading font" Display setting,
// same pattern as SHARED so every card component honours it without prop-drilling.
// `cardTitleClass()` is the ONE choke point: card TITLES call it instead of hardcoding
// className="serif". Notes are always sans (set at each note), bill AMOUNTS always serif.
const CARD_TITLE = { font:"serif" };
function cardTitleClass(){ return CARD_TITLE.font==="sans" ? "sans" : "serif"; }
// ── v239 · TIMES AND FIGURES FOLLOW THE FONT SETTING TOO ──────────────────────
// Until v239 only card TITLES honoured the Display setting: pick "Sans" and the titles
// turned Roboto Condensed while every time and every $ figure stayed Fraunces italic, so a single
// row mixed two typefaces. Mandy chose "everywhere" — row times, row amounts AND the big
// Bills/Work-Stats summary figures all switch.
//
// TWO helpers, not one, because they answer different questions:
//   numClass()  — follows the setting, same as titles. For $ amounts and hour figures.
//   timeClass() — ALWAYS "sans", in BOTH modes. Mandy's separate decision (option 3): a
//                 time is a fact to be read at a glance, not display type, and Fraunces
//                 gets fragile at the 11px times now ship at. Times therefore stop
//                 following the heading setting entirely — deliberate, not an oversight.
//
// TIME_STYLE is the single style object for a collapsed-row time. Upright (the italic is
// gone), 11px, semibold to survive the size drop, matching the uppercase category line
// beside it. Callers spread it and add their own colour.
function numClass(){ return CARD_TITLE.font==="sans" ? "sans" : "serif"; }
// The big Bills/Work figures were Fraunces ITALIC. Roboto Condensed has no true italic
// cut (v240; Archivo before it did not either), so a
// literal fontStyle:"italic" would make the browser SYNTHESISE a slant — a mechanically
// sheared sans, which looks broken rather than styled. numItalic() returns the italic
// only while the serif face is actually in use, and bumps weight in sans to keep the same
// presence on the page. Every display-size figure spreads this instead of hardcoding.
function numItalic(){
  return CARD_TITLE.font==="sans" ? {fontStyle:"normal",fontWeight:700} : {fontStyle:"italic"};
}
function timeClass(){ return "sans"; }
const TIME_STYLE = { fontSize:11, fontWeight:700, letterSpacing:.3, fontStyle:"normal" };
function rgbaFromHex(hex, a){
  const h=hex.replace("#","");
  const r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);
  return `rgba(${r},${g},${b},${a})`;
}
// A coloured glow box-shadow for a given hue, or "none" when glow is off.
function glowShadow(hex, strength=0.5, blur=12){
  if(!GLOW.on) return "none";
  return `0 0 ${blur}px ${rgbaFromHex(hex, strength)}`;
}

// HSL → hex, for the spectrum colour picker.
function hslToHex(h,s,l){
  s/=100; l/=100;
  const k=n=>(n+h/30)%12;
  const a=s*Math.min(l,1-l);
  const f=n=>{ const c=l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1))); return Math.round(255*c); };
  const to=x=>x.toString(16).padStart(2,"0");
  return `#${to(f(0))}${to(f(8))}${to(f(4))}`;
}

// Accent colour choices offered in Settings for each person.
// ── PERSON COLOURS ────────────────────────────────────────────────────────────
// The old set was eight variations on mud: saturation 28–60%, lightness 35–49 — every
// swatch in one narrow band, so nothing was vivid, deep or pale. Worse, it wasn't even
// eight colours: mauve and plum sat 12° apart on the wheel, and olive/moss/lime were all
// around h86. Three greens and a near-duplicate. Effectively ~5 distinct options.
//
// Jewel tones: saturated but DEEP, minimum hue gap 20°. Deep rather than vivid because
// these sit on a warm cream page — bright primaries there read as a children's app, and
// these also stay legible as tag text and scoreline chips, which is where they actually live.
const PERSON_COLORS = [
  "#BA2C73", // magenta
  "#2B5AAB", // sapphire
  "#D36322", // burnt orange
  "#277C52", // forest
  "#8639AC", // purple
  "#238B95", // teal
  "#CD981D", // gold
  "#B9273B", // crimson
];

// Old palette → new, BY SLOT. Deliberately positional, NOT nearest-colour.
//
// A nearest-colour map (CIELAB) COLLIDES: mauve and plum both land on magenta, olive and
// moss both land on forest. Two people whose colours were merely similar would come out
// IDENTICAL — and the person colour is the only thing distinguishing them on every tag,
// chip and stats bar in the app. Positional cannot collide, by construction: 8 in, 8 out.
//
// It's also semantically right. Nearest-colour sent slate BLUE to teal; slot-for-slot sends
// it to sapphire, which is what it obviously wanted to be.
const PERSON_COLOR_MIGRATION = {
  "#A65578":"#BA2C73",  // mauve      → magenta
  "#4A6E8C":"#2B5AAB",  // slate blue → sapphire
  "#B0623A":"#D36322",  // rust       → burnt orange
  "#6C8A44":"#277C52",  // olive      → forest
  "#8A4A72":"#8639AC",  // plum       → purple
  "#3E8080":"#238B95",  // teal       → teal
  "#C99A32":"#CD981D",  // mustard    → gold
  "#5A7340":"#B9273B",  // moss       → crimson
};
// Case-insensitive: the stored hex may have been written in either case over time.
function migratePersonColor(hex){
  if(!hex) return hex;
  const k=Object.keys(PERSON_COLOR_MIGRATION).find(o=>o.toLowerCase()===String(hex).toLowerCase());
  return k ? PERSON_COLOR_MIGRATION[k] : hex;   // a custom colour is left alone
}

// ─── LEVELS & REWARDS ────────────────────────────────────────────────────────
// THE FOURTH DEFINITION OF "WEEK". This app has three already and they are
// deliberately NOT the same thing:
//   weekStart   — the CALENDAR week (Sun or Mon), a display setting
//   otWeekKey   — the OVERTIME week (hard Saturday). "do not merge the two."
//   rewardReset — THIS ONE: which weekday a reward period rolls over on.
// Changing your goal reset day must NOT move your overtime week or your calendar.
// probe-period fails the build if this is wired into either of the others.
//
// rewardReset: 0=Sun … 6=Sat. Default 1 (Monday) — the old hard-coded behaviour,
// so an upgrade is invisible.
const REWARD_RESET_DEFAULT = 1;

// Start-of-period date for `d`, given the reset weekday. Local, at midday — never
// toISOString: see the timezone trap.
function periodWeekStart(d, reset=REWARD_RESET_DEFAULT){
  const dt=new Date(d.getFullYear(),d.getMonth(),d.getDate(),12,0,0,0);
  const back=(dt.getDay()-reset+7)%7;      // days since the last reset day
  dt.setDate(dt.getDate()-back);
  return dt;
}
function weekKey(d=new Date(), reset=REWARD_RESET_DEFAULT){
  return toLocalYMD(periodWeekStart(d,reset));
}
// A FORTNIGHT MUST BE ANCHORED, or "which fortnight is it" has no answer. It is
// anchored to the same weekday grid as the week, taking every OTHER reset day from
// a fixed epoch — so a fortnight always starts on the reset day and always contains
// exactly two of your weeks.
const FORT_EPOCH = new Date(1970,0,5,12,0,0,0);   // a Monday
function fortKey(d=new Date(), reset=REWARD_RESET_DEFAULT){
  const s=periodWeekStart(d,reset);
  const wks=Math.round((s-FORT_EPOCH)/(7*864e5));
  if(((wks%2)+2)%2) s.setDate(s.getDate()-7);     // snap back to the EVEN week
  return toLocalYMD(s);
}
function monthKey(d=new Date()){
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
}
// The LAST day of the period a key names — used for "5 days left" and for detecting
// a rollover. recurEnd-style: INCLUSIVE.
function periodEnd(period,key){
  if(period==="monthly"){
    const [y,m]=key.split("-").map(Number);
    return new Date(y,m,0,12,0,0,0);               // day 0 of next month = last of this
  }
  const [y,m,d]=key.split("-").map(Number);
  const e=new Date(y,m-1,d,12,0,0,0);
  e.setDate(e.getDate() + (period==="fortnightly"?13:6));
  return e;
}
// Given a stored periods object, return one with current buckets, zeroing any bucket
// whose key has rolled over.
function freshPeriods(p,reset=REWARD_RESET_DEFAULT){
  const wk=weekKey(new Date(),reset), fk=fortKey(new Date(),reset), mk=monthKey();
  const week =(p&&p.week &&p.week.key ===wk)?p.week :{key:wk,her:0,him:0};
  const fort =(p&&p.fort &&p.fort.key ===fk)?p.fort :{key:fk,her:0,him:0};
  const month=(p&&p.month&&p.month.key===mk)?p.month:{key:mk,her:0,him:0};
  return {week,fort,month};
}

// LIFETIME IS GONE. A stored lifetime goal must become SOMETHING on upgrade, and it
// must not become Weekly: a 200-point goal built to run for months would get seven
// days and read as broken. It migrates to MONTHLY, the longest period left.
// `claimed` (the lifetime surplus bank) is KEPT IN STORAGE, not deleted — dead data
// while lifetime is gone, but unrecoverable if wiped and she ever wants it back.
// HIDE, NEVER WIPE.
const REWARD_PERIODS=[["weekly","Weekly"],["fortnightly","Fortnightly"],["monthly","Monthly"]];
// MODULE SCOPE, DELIBERATELY. This was a `const` inside the component, declared at line
// ~4800 — but awardPoints reads it at ~3180 to label the goal burst. A const is NOT
// hoisted, so that is a TEMPORAL DEAD ZONE: it compiles, it renders in a smoke test that
// never awards points, and it throws the moment a goal is met. It has no dependencies and
// belongs with the other period constants.
const periodLabel={weekly:"This week",fortnightly:"This fortnight",monthly:"This month"};
const PERIOD_KEYS=REWARD_PERIODS.map(([v])=>v);
function migratePeriod(p){ return PERIOD_KEYS.includes(p) ? p : "monthly"; }

// ── THE ONE GATE ─────────────────────────────────────────────────────────────
// EVERY reader of a goal's period goes through these. Nine sites used to test
// `period==="weekly" ? week : month` DIRECTLY — with MONTH as the fallback — so a new
// value would not crash, it would SILENTLY COUNT AGAINST THE MONTHLY BUCKET. That is
// exactly how the Projects bug worked. probe-period fails the build on a bare
// comparison. Do not add a tenth reader; add a case here.
function periodBucket(period,fp){
  const p=migratePeriod(period);
  return p==="weekly" ? fp.week : p==="fortnightly" ? fp.fort : fp.month;
}
function periodKeyOf(period,fp){ return periodBucket(period,fp).key; }

// ── NARROWING STEALS POINTS. WIDENING NEVER DOES. ────────────────────────────
// The three buckets are NOT independent tallies — awardPoints bumps ALL THREE on
// every completion. They are NESTED WINDOWS over one stream, diverging only because
// they reset at different times. Therefore month >= fort >= week, ALWAYS.
//
// So WIDENING (week -> month) can only ever GAIN: the longer window already contains
// everything the shorter one saw. It is always safe and is never blocked.
//
// NARROWING (month -> week) is the ONLY direction that can lose points, because the
// shorter window genuinely did not see the older ones. Switching a met 150/100 goal
// from Monthly to Weekly dropped it to 40/100 and DESTROYED THE EARNED TREAT. That
// is the bug.
//
// We do NOT "carry" the points across. Writing a month's points into the week bucket
// would make the ROLLOVER SNAPSHOT log a week that scored 40 as having scored 150 —
// permanently. That is the "catch up all" points farm wearing a different hat: paying
// out for something that did not happen in that window. An entry is FROZEN at rollover
// because that is what it was. So instead: a narrowing change is LOCKED while the
// period is running.
const PERIOD_RANK={weekly:0,fortnightly:1,monthly:2};
function periodRank(p){ return PERIOD_RANK[migratePeriod(p)]; }
// Returns null if the switch is allowed, else {cost,from,to,unlocks} describing what
// it would take. Only ever non-null for a NARROWING that would actually lose points —
// if both buckets read the same there is nothing to steal, so do not block for nothing.
function periodLock(from,to,who,fp){
  if(periodRank(to)>=periodRank(from)) return null;        // widening (or same): always safe
  const cur=periodBucket(from,fp), next=periodBucket(to,fp);
  const val=(b)=>who==="shared" ? (b.her||0)+(b.him||0) : (b[who]||0);
  const cost=val(cur)-val(next);
  if(cost<=0) return null;                                  // nothing would be lost
  return { cost, from:val(cur), to:val(next), unlocks:periodEnd(from,cur.key) };
}

// ── THE GOAL LOG ─────────────────────────────────────────────────────────────
// "A treat stays claimable FOREVER until claimed" is not a display rule — it moves
// where the truth lives. A goal used to store `claimedKey`: ONE string, able to say
// "this period is claimed" and NOTHING ELSE. It cannot express "three past periods
// were met, two are still owed."
//
// So the log IS the source of truth for what is owed. Each entry carries its own
// `claimed` flag, and claiming writes back INTO THE ENTRY, never into the goal.
// `claimedKey` is thereby retired — but is NOT deleted from storage. HIDE, NEVER WIPE.
//
// AN ENTRY IS FROZEN AT ROLLOVER. Score, target, treat and dates are captured as they
// were. Nothing recomputes them later: raise the target from 150 to 200 tomorrow and
// last fortnight's row still reads 150, because that is what it was.
//
// id = `${who}:${period}:${key}` — stable and unique, so a rollover that fires twice
// (two tabs, a re-mount) cannot double-log. entryId is the ONLY dedupe key.
function entryId(who,period,key){ return `${who}:${period}:${key}`; }

function makeEntry(who,goal,key,scored){
  const period=migratePeriod(goal.period);
  const target=Math.max(1,goal.target||1);
  return {
    id:entryId(who,period,key),
    who, period, key,
    treat:goal.treat||"",
    target,
    score:Math.max(0,scored||0),
    met:(scored||0)>=target,
    ends:toLocalYMD(periodEnd(period,key)),
    claimed:false,
  };
}
// A treat that is owed: met, and not yet claimed. It NEVER expires.
function isOwed(e){ return !!(e && e.met && !e.claimed); }
function owedCount(log,who){
  return (log||[]).filter(e=>isOwed(e) && (who===undefined || e.who===who)).length;
}
// TREATS WAITING = the ONE answer to "does this person have something to claim?" *(v203)*
//
// There are TWO sources and they are not interchangeable:
//   • `goalLog`  — periods that have ALREADY ROLLED OVER. `owedCount` reads this.
//   • live progress — the CURRENT period, which is not in the log yet and won't be
//     until it rolls. `goalProgress(...).met` reads this.
//
// The name-card trophy counted only the first, so a goal met TODAY lit nothing while
// the record sheet (which reads the second) offered Claim on the same screen. Same
// question, two answers. This helper asks both.
//
// `goalProgress` already returns met:false once the current period is claimed, so a
// claimed treat cannot keep the trophy alive.
//
// NB: `rewards`/`fp` are required to see the current period. Called WITHOUT them it
// degrades to the old rolled-over-only count rather than throwing — which is exactly
// what the dashboard gold card still wants (Mandy's call: trophy only at v203).
// NOTE: this is a function DECLARATION so it hoists; it calls goalProgress, which is
// defined much further down the file but is likewise hoisted.
function treatsWaiting(log,who,rewards,points,fp){
  let n=owedCount(log,who);
  if(rewards&&fp&&who&&who!=="shared"){
    const g=rewards[who]||DEFAULT_REWARDS[who];
    if(g&&goalProgress(g,who,points,fp,log).met) n+=1;
  }
  return n;
}
// 0=Sun … 6=Sat, matching Date.getDay() — do NOT reorder, the index IS the value stored
// in hb_rewardReset and consumed by periodWeekStart.
// NB: DOW_SHORT already exists further down as ["Sun","Mon",…] and is used by the plan
// UI. These are DELIBERATELY separate names — redefining that one silently relabels a
// screen that has nothing to do with rewards.
const DOW_INITIAL=["S","M","T","W","T","F","S"];
const DOW_FULL   =["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
// Whole days from `today` to the INCLUSIVE last day of the period. 0 = it ends today.
function daysUntil(endDate,today){
  const a=new Date(today.getFullYear(),today.getMonth(),today.getDate(),12,0,0,0);
  const b=new Date(endDate.getFullYear(),endDate.getMonth(),endDate.getDate(),12,0,0,0);
  return Math.max(0,Math.round((b-a)/864e5));
}
function daysLabel(n){ return n<=0?"Last day":n===1?"1 day left":`${n} days left`; }


// Per-person level curve, configurable in Settings.
//   base = cost of reaching level 2
//   grow = how much MORE each subsequent level costs (0 = flat levels)
// So level n costs: base + (n-2)*grow. With base 60, grow 0 this is the old
// behaviour exactly (a flat 60/level), which is why the migration is invisible.
//
// Live module-scope object mutated in place by applyLevels — same pattern as C,
// PTS and ROOM_META. levelInfo() is called from four places and is not a hook, so
// threading config through every call site would be far more invasive than this.
const LEVELS = { base:60, grow:0 };
function applyLevels(cfg){
  LEVELS.base = Math.max(1, cfg&&cfg.base || 60);
  LEVELS.grow = Math.max(0, (cfg&&cfg.grow) ?? 0);
}
// Points needed to complete level n (i.e. to go from level n to n+1).
function levelCost(n){ return LEVELS.base + Math.max(0,n-1)*LEVELS.grow; }

function levelInfo(pts){
  let p = Math.max(0, pts||0);
  // Walk the bands. With grow>0 there's no closed form worth the confusion, and
  // the loop is bounded in practice — but guard it anyway: a tiny base with a huge
  // points total shouldn't be able to spin forever.
  let level = 1;
  let need = levelCost(1);
  let guard = 0;
  while(p >= need && guard++ < 10000){
    p -= need;
    level++;
    need = levelCost(level);
  }
  const into = p;                            // points into the CURRENT level
  const pct = Math.max(0, Math.min(1, into/need));
  return { level, into, need, pct, toNext: need-into };
}

// ─── BILLS ────────────────────────────────────────────────────────────────────
// A bill is a task with taskKind:"bill". It reuses the ENTIRE task machinery —
// recurrence, assignee, due dates, the calendar, points — and adds two things:
//   series.amount            the EXPECTED amount (what it usually costs)
//   exceptions[date].amount  the ACTUAL amount paid for that occurrence
//
// The second is the whole trick. `exceptions[date]` already stores per-occurrence
// state (done, doneAt, award, subDone) and materialize() spreads it over the series,
// so a per-occurrence amount needed NO new data model and NO migration — the paid
// history is just the exceptions map read back.
const BILL_KIND="bill";
const BILL_COLOR="#4FA3E8";   // same blue as the Appointment event category

// ─── BUTTON STANDARD *(v259)* ────────────────────────────────────────────────
// ONE bin, ONE height, ONE radius, everywhere. Mandy audited the whole app and found
// FOURTEEN delete/remove controls drawn seven different ways: icon sizes 9/13/14/15/17px,
// two different bin glyphs, five controls using a bare "×" character, six explicit button
// heights, twelve padding combinations and ten border radii.
//
// THE GLYPH IS THE STRAIGHT-BODIED BIN WITH TWO VERTICAL LINES (Mandy's pick). It already
// existed in the icon catalog as the "trash" CHORE CATEGORY icon but no delete button used
// it. Declared here as the single source for delete controls; the catalog entry stays where
// it is because a chore category and a button icon are different things that merely happen
// to look alike, and merging them would mean a category rename could change every button.
//
// STROKE 1.9 AND linejoin ROUND to match the rest of the icon set. The catalog is
// stroke-only - a filled path renders mangled - so this must never gain a fill.
//
// 28px is the SMALLEST height that still holds a 14px icon with breathing room. Mandy asked
// for 14px; at that height the button would be shorter than its own icon and would clip
// 12px text, which needs ~16px of line box. Recorded because it will look arbitrary later:
// 28 is a floor set by the contents, not a taste. Note this is already below the 44px touch
// target phones are designed around - going smaller trades tap accuracy for tidiness.
//
// DECLARED ABOVE TrashIcon ON PURPOSE. `size=BTN_ICON` is a default parameter, so it is
// evaluated at CALL time and happens to work below the definition - but that is luck, not
// design: it holds only while nothing invokes TrashIcon at module scope. The same TDZ trap
// as TOIL_COLOR/DAYOFF_META. Ordering it correctly costs nothing and removes the hazard.
const BTN_H=28;          // every action-row button
const BTN_ICON=14;       // every icon inside one
const BTN_R=10;          // corner radius
const BTN_PAD="0 11px";  // horizontal only - the height is fixed, so vertical padding fights it

// The REMOVE-FROM-LIST cross. Five controls drew this as a bare "×" TEXT character at
// three different font sizes (13/15/18px), so it rendered in whatever face the element
// inherited and sat off-centre. A stroked glyph matches the rest of the icon set and
// centres properly. Smaller than BTN_ICON on purpose: these sit inside chips and rows, not
// in an action row, and a full-size bin-scale cross would dominate the thing it removes.
function RemoveIcon({size=11}){
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2.4" strokeLinecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>;
}
function TrashIcon({size=BTN_ICON}){
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round">
    <path d="M10 11v6"/><path d="M14 11v6"/>
    <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/>
    <path d="M3 6h18"/>
    <path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
  </svg>;
}

// Bill categories REPLACE the room categories on a bill — a bill is an Electricity
// bill, not a Kitchen bill. Stored on the task as `billCat`, so `room` is left alone
// and a bill switched back to a task still has its room intact.
const DEFAULT_BILL_CATS = {
  Electricity:  { color:"#F0C13C", icon:"bolt" },
  Water:        { color:"#4FA3E8", icon:"waterdrop" },   // v262 · was `drop`; superseded
  Gas:          { color:"#FF8A3C", icon:"flame" },
  Mortgage:     { color:"#5EE7B4", icon:"home" },
  Rent:         { color:"#D98AFF", icon:"building" },
  Internet:     { color:"#38C6FF", icon:"wifi" },
  Phone:        { color:"#57D964", icon:"phone" },
  Insurance:    { color:"#FF6B5C", icon:"shield" },
  Council:      { color:"#A78BFA", icon:"bank" },
  Subscription: { color:"#E85D9E", icon:"repeat" },
  Car:          { color:"#AEB6C4", icon:"truck" },
  Afterpay:     { color:"#5EE7B4", icon:"card" },
  // v276 · CREDIT CARD is a DEFAULT category, not something the user must invent. It is
  // the category the card picker filters on, so a fresh install can use card-linking
  // without first building the category by hand.
  "Credit Card": { color:"#E85D9E", icon:"card" },
  Other:        { color:"#8A93A8", icon:"card" },
};
// The category that marks a bill as a CREDIT CARD. Mandy chose the category route over a
// separate flag (v276). Links themselves are keyed on the card bill's ID, never this name,
// so renaming the category cannot orphan a link — see cardBills()/linkedCharges().
const CARD_CAT="Credit Card";
// The card accent. Read from the LIVE category map so a recoloured Credit Card category
// repaints every card surface at once — one source of truth, same rule as WORK_TOKENS.
// Falls back to the default pink if the category was deleted.
const CARD_TINT_OF=cats=>((cats&&cats[CARD_CAT])||DEFAULT_BILL_CATS[CARD_CAT]).color;

// ── CARD TERMS AND THE MINIMUM PAYMENT *(v279)* ───────────────────────────────
// Stored on the card bill as `cardTerms:{limit,apr,minPct,minAmt}`. ALL OPTIONAL —
// a card with no terms behaves exactly as it did before this existed.
//
// THE MINIMUM RULE, as Mandy entered it from her own statement: the greater of a
// PERCENTAGE of the balance and a FLAT FLOOR. Defaults are NOT applied — an
// invented 2%/$30 would look authoritative and be wrong for her card. If she has
// not entered a rule there is no minimum to offer, and the option is hidden.
//
// Money is rounded to cents at the LAST step only. Rounding the percentage before
// comparing it to the floor picks the wrong branch when the two are within a cent.
const r2=n=>Math.round((Number(n)||0)*100)/100;
function cardMinPayment(balance, terms){
  const bal=parseAmt(balance);
  if(!terms||bal<=0) return null;
  const pct=Number(terms.minPct)||0, floor=Number(terms.minAmt)||0;
  if(pct<=0&&floor<=0) return null;          // no rule entered → no minimum to offer
  const byPct=bal*(pct/100);
  // "Whichever is GREATER" — but never more than the balance itself: a $12 balance on a
  // $30 floor is a $12 payment, not a $30 one.
  return r2(Math.min(bal, Math.max(byPct, floor)));
}
// ONE MONTH of interest at the annual rate, on what is left AFTER the payment.
//
// THIS IS AN ESTIMATE AND IS LABELLED AS ONE EVERYWHERE IT APPEARS. Real card interest
// is calculated DAILY on the running balance, and is affected by mid-month purchases,
// cash-advance rates, fees and any interest-free period — none of which this app can
// see. It divides the annual rate by 12 rather than pretending to daily accuracy it
// does not have. It must NEVER write to the stored balance: Mandy types what her
// statement says, and the estimate only ever describes.
function cardInterestEst(balanceAfter, apr){
  const bal=parseAmt(balanceAfter), rate=Number(apr)||0;
  if(bal<=0||rate<=0) return 0;
  return r2(bal*(rate/100)/12);
}
// How much of a payment actually reduces the DEBT once next month's interest is added
// back. The number that makes a minimum payment legible: paying $36.85 while $31.58 is
// interest moves the debt by $5.27, and nothing else on the sheet shows that.
function cardPrincipalEst(balance, payment, apr){
  const bal=parseAmt(balance), pay=parseAmt(payment);
  if(bal<=0||pay<=0) return 0;
  const after=Math.max(0, bal-pay);
  return r2(pay - cardInterestEst(after, apr));
}
const BILL_CATS = JSON.parse(JSON.stringify(DEFAULT_BILL_CATS));
function applyBillCats(cats){
  Object.keys(BILL_CATS).forEach(k=>{ delete BILL_CATS[k]; });
  Object.assign(BILL_CATS, cats);
  if(!BILL_CATS.Other) BILL_CATS.Other = {...DEFAULT_BILL_CATS.Other};   // always a fallback
}
// ─── BNPL / AFTERPAY ──────────────────────────────────────────────────────────
// A fixed total split into N equal instalments on a repeating weekday. NOT a
// recurring bill: a recurring bill runs forever with a varying amount, a BNPL plan
// has a known total and ENDS after N payments.
//
// Stored on the bill as `plan`:
//   {total, count, everyDays, weekday, upfront, dates:[...]}
// The dates are BAKED at save time rather than recomputed on every render — the
// schedule is a contract with the lender, so it must not silently change if the
// user's clock or the app's stepping logic ever moves.
const isPlan = t => !!(t && t.plan && Array.isArray(t.plan.dates) && t.plan.dates.length);
// A PLAN'S DUE DATE IS ITS FIRST INSTALMENT *(v264)*.
// Save stamps `dueDate:dates[0]`, but plans created before that line carry a plan with a
// baked schedule and NO dueDate. Every reader that asks a bill for `dueDate` — the Bills
// row builder, the auto-pay sweep — then gets undefined and silently drops the plan: no
// row in the list, no sweep, while the dashboard and nav badge (which read plan.dates
// directly) still count it. One missing field, three disagreeing surfaces.
//
// This is the READ-SIDE repair. It is deliberately NARROWER than a migration: it does not
// rewrite stored records, it just refuses to let a plan's own schedule be ignored because
// a denormalised copy of its first date is absent. `dueDate` still wins when present, so a
// plan whose first instalment was edited is unaffected.
const planDueDate = t => (t && t.dueDate) || (isPlan(t) ? t.plan.dates[0] : undefined);
const DOW_SHORT=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
const dowOf = ymd => new Date(ymd+"T00:00:00").getDay();
const onOrAfterDow = (from, wd) => { let d=from; let g=0; while(dowOf(d)!==wd && g++<7) d=addDays(d,1); return d; };

// Build the instalment dates.
//
// The 2nd payment is a FULL CYCLE after the upfront one, then snapped forward to the
// payment weekday — NOT merely the next occurrence of that weekday. Paying upfront on
// a Sunday with a Monday payment day gives Mon 27 Jul, not Mon 13 Jul: the fortnightly
// cycle is anchored to the payment you just made, not to the calendar week.
function bnplDates({start, count, everyDays=14, weekday, upfront}){
  const out=[];
  let first;
  if(upfront){
    out.push(start);
    first = onOrAfterDow(addDays(start, everyDays), weekday);
  } else {
    // A GRACE WEEK BEFORE THE FIRST PAYMENT *(v112)*
    //
    // This used to be onOrAfterDow(start, weekday) — the very next payment weekday. Buy on
    // a Sunday with Thursday payments and the first instalment fell FOUR DAYS LATER. No BNPL
    // lender works that way: with nothing paid up front, the first instalment sits roughly a
    // fortnight out, not the same week.
    //
    // The rule is ADD A WEEK, THEN FIND THE NEXT PAYMENT WEEKDAY. Buy Sun 14 Jun, Thursdays:
    // 14 Jun + 7 = 21 Jun (a Sunday), and the next Thursday from there is 25 Jun. Correct.
    //
    // NOT `addDays(start, everyDays)`. Adding a full cycle overshoots to 2 Jul — it skips a
    // payment weekday entirely, which stretches a 4-payment plan a fortnight beyond where the
    // lender would end it. The grace period is one week; the CADENCE is everyDays. They are
    // different quantities and conflating them was the bug.
    //
    // Instalments 2..n step by everyDays as normal, so only the first date moves.
    first = onOrAfterDow(addDays(start, 7), weekday);
  }
  let d=first;
  while(out.length<count){ out.push(d); d=addDays(d, everyDays); }
  return out;
}

// Split a total into `count` equal instalments. The remainder lands on the LAST one,
// so the instalments always sum EXACTLY to the total — $100 over 3 is 33.33 / 33.33 /
// 33.34, never 3 x 33.33 = 99.99 with a cent unaccounted for.
function bnplSplit(total, count){
  const t=Math.round(parseAmt(total)*100);
  const per=Math.floor(t/count);
  const amts=Array(count).fill(per);
  amts[count-1] = t - per*(count-1);
  return amts.map(c=>c/100);
}

// Everything a plan needs, derived from the stored `plan` + the exceptions map.
function planProgress(t){
  if(!isPlan(t)) return null;
  const {dates,total}=t.plan;
  const ex=t.exceptions||{};
  // A deleted instalment is not a paid one — see deleteTask (v105). Legacy records can
  // carry BOTH flags, so guard here too or "2 of 4 paid" counts an instalment you removed.
  const paid=dates.filter(d=>ex[d]&&ex[d].done&&!ex[d].deleted);
  const paidAmt=paid.reduce((a,d)=>a+parseAmt(ex[d].amount ?? 0),0);
  return {
    total:parseAmt(total), dates,
    paidCount:paid.length, count:dates.length,
    paidAmt, remaining:Math.max(0, parseAmt(total)-paidAmt),
    done:paid.length>=dates.length,
  };
}

