// ── Mortgage amortisation engine v2 (v307 fix) ──────────────────────────────
// Actual/actual daily interest. Offset account is separate from loan principal —
// interest accrues on (balance - offset). Weekly repayments come out of offset
// and directly reduce the loan balance. Repayment amount is recalculated using
// standard P&I amortisation formula whenever the interest rate changes.
function mortWeeklyPmt(balance, annualRate, weeksRemaining){
  if(weeksRemaining<=0||balance<=0) return balance;
  const r=annualRate/52;
  if(r<0.00001) return balance/Math.max(1,weeksRemaining);
  return balance*r*Math.pow(1+r,weeksRemaining)/(Math.pow(1+r,weeksRemaining)-1);
}

function mortCalc(cfg, today){
  const {loanAmount,startDate,loanTermYears,offsetStart,rateChanges,transactions}=cfg;
  if(!loanAmount||!startDate||!rateChanges||!rateChanges.length) return null;
  const termYears=loanTermYears||30;
  const totalWeeks=Math.round(termYears*52);

  // Sorted rate schedule
  const rates=[...rateChanges].sort((a,b)=>a.date.localeCompare(b.date));
  function rateOn(ymd){
    let r=rates[0].rate;
    for(const rc of rates){ if(rc.date<=ymd) r=rc.rate; else break; }
    return r/100;
  }

  // Expand transactions into a per-date event map
  function expandTx(tx,endYmd){
    const events=[];
    const sign=tx.type==="cost"?-1:1;
    const amt=parseAmt(tx.amount)*sign;
    const acct=tx.account||"offset";
    if(!amt) return events;
    if(tx.freq==="once"||tx.dateMode==="once"){
      const d=tx.date||tx.dateFrom;
      if(d&&d<=endYmd) events.push({date:d,amount:amt,account:acct});
      return events;
    }
    let cursor=tx.dateFrom;
    if(!cursor) return events;
    const untilDate=tx.dateMode==="until"||tx.dateMode==="between"?(tx.dateTo||endYmd):endYmd;
    const months={"monthly":1,"quarterly":3,"twice-yearly":6,"yearly":12}[tx.freq];
    const days={"daily":1,"weekly":7,"fortnightly":14,"four-weekly":28}[tx.freq];
    let itr=0;
    while(cursor<=untilDate&&itr<3000){
      if(cursor>=startDate) events.push({date:cursor,amount:amt,account:acct});
      if(months){ cursor=addMonths(cursor,months); }
      else if(days){ const d=new Date(cursor+"T00:00:00"); d.setDate(d.getDate()+days); cursor=toLocalYMD(d); }
      else break;
      itr++;
    }
    return events;
  }

  const maxEnd=addMonths(startDate,Math.round(termYears*12)+120); // term + 10yr buffer
  const allTx=(transactions||[]).flatMap(tx=>expandTx(tx,maxEnd));
  const txOffByDate={};
  const txLoanByDate={};
  allTx.forEach(e=>{
    if(e.account==="loan") txLoanByDate[e.date]=(txLoanByDate[e.date]||0)+e.amount;
    else txOffByDate[e.date]=(txOffByDate[e.date]||0)+e.amount;
  });

  let balance=loanAmount;
  let offset=offsetStart||0;
  const startD=new Date(startDate+"T00:00:00");
  const firstRepayD=new Date(startD); firstRepayD.setDate(firstRepayD.getDate()+7);
  let nextRepay=toLocalYMD(firstRepayD);
  let weeksDone=0;
  let currentRate=rateOn(startDate);
  // Per-rate override: each rate change can have its own weeklyPmtOverride
  function overrideForRate(rateDate){
    const rc=rates.find(r=>r.date===rateDate);
    return rc?.weeklyPmtOverride||0;
  }
  const startOverride=overrideForRate(startDate);
  let weeklyPmt=startOverride>0?startOverride:mortWeeklyPmt(balance,currentRate,totalWeeks);

  // Per-rate-change scheduled repayment amounts (shown in UI)
  const rateSchedule=[{date:startDate,rate:rates[0].rate,weeklyPmt:Math.round(weeklyPmt),isOverride:startOverride>0}];

  const snapshots=[];
  let lastSnapYear="";
  let totalInterest=0;
  let todayBalance=null,todayOffset=null,todayInterest=null,todayWeeklyPmt=null;
  let totalRepayments=0;
  let payoffDate=null;
  let cursor=startDate;
  let itr=0;

  while(balance>0.50&&cursor<maxEnd&&itr<25000){
    // Check rate change → recalculate weekly repayment
    const newRate=rateOn(cursor);
    if(Math.abs(newRate-currentRate)>0.00001&&cursor>startDate){
      currentRate=newRate;
      const weeksLeft=Math.max(1,totalWeeks-weeksDone);
      const rateOverride=overrideForRate(cursor);
      weeklyPmt=rateOverride>0?rateOverride:mortWeeklyPmt(balance,currentRate,weeksLeft);
      // Record for UI
      const existing=rateSchedule.find(r=>r.date===cursor);
      if(existing){ existing.weeklyPmt=Math.round(weeklyPmt); existing.isOverride=rateOverride>0; }
      else rateSchedule.push({date:cursor,rate:currentRate*100,weeklyPmt:Math.round(weeklyPmt),isOverride:rateOverride>0});
    }

    // Daily interest on net balance (loan minus offset)
    const net=Math.max(0,balance-offset);
    const dailyInterest=net*(currentRate/365);
    balance+=dailyInterest;
    totalInterest+=dailyInterest;

    // Apply offset transactions (deposits/withdrawals to offset account)
    if(txOffByDate[cursor]) offset=Math.max(0,offset+txOffByDate[cursor]);
    // Apply loan transactions (direct payments to loan principal)
    if(txLoanByDate[cursor]) balance=Math.max(0,balance-txLoanByDate[cursor]);

    // Weekly repayment — debits offset, credits loan principal directly
    if(cursor===nextRepay){
      const repay=Math.min(weeklyPmt,balance);
      offset=Math.max(0,offset-repay);
      balance-=repay;
      totalRepayments+=repay;
      const nd=new Date(nextRepay+"T00:00:00"); nd.setDate(nd.getDate()+7);
      nextRepay=toLocalYMD(nd);
      weeksDone++;
    }

    // Snapshot today's values
    if(cursor===today){
      todayBalance=Math.max(0,Math.round(balance));
      todayOffset=Math.round(offset);
      todayInterest=Math.round(totalInterest);
      todayWeeklyPmt=Math.round(weeklyPmt);
    }

    // Yearly snapshots for chart — switch to monthly in the final 2 years for smooth convergence
    const ym=cursor.slice(0,7);
    const yr=cursor.slice(0,4);
    const nearPayoff=balance>0&&offset>0&&(offset/balance)>0.6; // within striking distance
    if(nearPayoff){
      // Monthly snapshots when offset is approaching balance
      if(ym!==lastSnapYear){
        snapshots.push({date:ym,balance:Math.max(0,Math.round(balance)),offset:Math.round(offset)});
        lastSnapYear=ym;
      }
    } else if(yr!==lastSnapYear){
      snapshots.push({date:ym,balance:Math.max(0,Math.round(balance)),offset:Math.round(offset)});
      lastSnapYear=yr;
    }

    // End when fully offset (offset >= balance)
    if(offset>=balance&&balance>0){
      payoffDate=cursor;
      snapshots.push({date:cursor.slice(0,7),balance:Math.round(balance),offset:Math.round(offset)});
      break;
    }
    if(balance<=0.50){
      payoffDate=cursor;
      snapshots.push({date:cursor.slice(0,7),balance:0,offset:Math.round(offset)});
      break;
    }
    const nd=new Date(cursor+"T00:00:00"); nd.setDate(nd.getDate()+1);
    cursor=toLocalYMD(nd);
    itr++;
  }

  return {
    balance:todayBalance??Math.max(0,Math.round(balance)),
    offset:todayOffset??Math.round(offset),
    payoffDate,
    snapshots,
    rateNow:currentRate,
    weeklyPmt:todayWeeklyPmt??Math.round(weeklyPmt),
    interestToDate:todayInterest??Math.round(totalInterest),
    totalInterestPaid:Math.round(totalInterest),
    rateSchedule,
    totalRepayments:Math.round(totalRepayments),
  };
}
function billAverage(hist, method){
  const amts=(hist||[]).map(h=>parseAmt(h.amount)).filter(a=>a>0);
  if(!amts.length || method==="off") return 0;
  if(method==="median"){
    const s=[...amts].sort((a,b)=>a-b);
    const m=Math.floor(s.length/2);
    return s.length%2 ? s[m] : (s[m-1]+s[m])/2;
  }
  // hist is newest-first, so last3 = the first three.
  const use = method==="last3" ? amts.slice(0,3) : amts;
  return use.reduce((a,b)=>a+b,0)/use.length;
}
const isBill=t=>t&&t.taskKind===BILL_KIND;
// What to CALL a saved record in a toast. One definition, because "added" and "updated"
// were two separate strings that had already drifted ("Bill updated" existed on the
// recurring path while the one-off path still said "Task updated").
function savedLabel(t,verb){
  const what = !isBill(t) ? "Task" : (t.billCat===CARD_CAT ? "Credit card" : "Bill");
  return what+" "+verb;
}

// ── CREDIT CARD LINKING *(v276)* ──────────────────────────────────────────────
// THE PROBLEM: most direct debits are charged to a credit card, and the card bill
// was ALSO entered by hand. Every summary counted the money twice — once as
// Electricity, once inside the card's balance.
//
// THE RULE, and it is the whole feature:
//   A card-charged bill is REAL. It keeps its amount, its category, its history
//   and its own row in the graph. It is excluded from SUMMARY TOTALS only,
//   because the card bill already contains it.
//
// So `onCard` NEVER touches billHistory, monthlySpend, fairness or the category
// graph. Mandy was explicit: she still wants to see what each bill costs. It is a
// TOTALS rule, not a data rule. Anything that changes what a bill IS would be wrong.
//
// A card is a bill in the CARD_CAT category. The link is stored as `cardId` — the
// card bill's OWN id — never the category name and never the card's title. Two
// cards can share a name, and a category can be renamed; an id survives both. This
// is the same lesson as goalEntryId in v273: key on the id, never the name.
const isCardBill=t=>isBill(t)&&(t.billCat||"")===CARD_CAT;
// A bill CHARGED to a card. Requires BOTH the flag and a resolvable link, so a bill
// whose card was deleted falls back to behaving like an ordinary bill (it starts
// counting in totals again) rather than vanishing from every total silently.
const isOnCard=(t,cards)=>!!(t&&t.onCard&&t.cardId&&(!cards||cards.some(c=>c.id===t.cardId)));
// Every card in the household. Plain bills in the card category.
const cardBills=tasks=>(tasks||[]).filter(isCardBill);
// The bills charged to one card. `tasks` may be raw series or materialised
// occurrences — both carry cardId, so both work.
const chargesFor=(tasks,cardId)=>(tasks||[]).filter(t=>isBill(t)&&t.onCard&&t.cardId===cardId&&!isCardBill(t));

// ── WHICH MONTH A STATEMENT BELONGS TO *(v291)* ───────────────────────────────
// A CARD STATEMENT IS A CONTAINER, NOT A PAYMENT. Every other bill in this app is
// filed by the day the money left — correct for electricity, wrong for a card. The
// statement Mandy pays on 4 August holds spending from 24 June to 23 July, and paying
// it EARLY on 23 July filed it into July alongside the statement that actually was
// July's. Two statements in one month, and a July total $2,994.04 too high.
//
// `stmtYM` ("YYYY-MM") is the month the user says the statement is FOR. It is written
// once when the statement is added — predicted, then editable — and read here.
//
// THE FALLBACK IS THE OLD BEHAVIOUR, EXACTLY. No stmtYM (every non-card bill, and
// every statement recorded before this existed) → paidYMD → the due date. Nothing
// that does not carry the field can change what it does.
//
// SIX READERS call this. They are the six places a payment becomes a month:
// pastGroups, monthlySpend, netCards, homeBillPaidMo, paidWindow and fairness. The
// rule lives HERE and nowhere else — the v283/v284 lesson is that the same money
// reaching several surfaces must be routed through ONE helper, or a fix lands on
// whichever surface was being looked at and the others quietly disagree.
const spendYM=h=>{
  if(!h) return "";
  if(h.stmtYM) return h.stmtYM;                      // an explicit answer always wins
  // A CARD STATEMENT WITH NO STORED MONTH derives it: the month before its due date,
  // the same rule the backfill and the add sheet use *(v293)*. This makes filing
  // correct on render even for statements a migration never reached — the class of bug
  // behind "two statements in July". Requires billHistory to tag records with isCard.
  if(h.isCard && h.date){ const [y,m]=h.date.split("-").map(Number); if(y&&m){ const p=new Date(y,m-2,1); return `${p.getFullYear()}-${String(p.getMonth()+1).padStart(2,"0")}`; } }
  return ((h.paidYMD||h.date)||"").slice(0,7);        // every non-card bill: unchanged
};

// WHAT A STATEMENT COST, as opposed to what is owed on it.
//
// Mandy pays amounts off the card THROUGHOUT the month, so the balance due at the
// close of a statement is NOT what she spent in that period. `stmtCharges` is the
// total charged; the amount is what is still owing. Her words: the amount due is a
// reminder to pay, the total charges is the amount actually spent.
//
// The SPEND GRAPH asks what was spent, so it reads this. The BILLS LIST asks what
// leaves the account, so it keeps reading the amount — same rule the rest of the
// app follows, and mixing the two is how the double-counting started.
//
// Empty → the amount, so a statement with no charges entered draws exactly as it
// does today. An empty field must never make a month vanish from the graph.
const spendAmt=h=>(h&&h.stmtCharges!=null&&h.stmtCharges!=="") ? parseAmt(h.stmtCharges) : (h?h.amount:0);

// What has already gone in: charged minus still-owing. DERIVED — never stored, so it
// cannot drift from the two numbers it comes from.
//
// Returns null unless the result is a real, positive figure. Charges EQUAL to the
// amount means nothing has been paid yet; charges BELOW it means a balance carried
// over from a previous month, and subtracting would report a negative "already paid".
// In both cases the caller draws no line at all rather than drawing a wrong one.
const stmtPaidSoFar=h=>{
  // NOTE: this first guard is REDUNDANT against the sign test below for every value
  // reachable in this app — an unset stmtCharges parses to 0, and 0 minus a bill amount
  // is never positive because a bill amount is never negative. It was mutation-tested
  // and SURVIVED. It is kept because it states the intent ("no charges entered means no
  // answer") rather than leaving that to a coincidence of arithmetic, but do not expect
  // a probe to defend it, and do not add an unreachable fixture to make one appear to.
  if(!h||h.stmtCharges==null||h.stmtCharges==="") return null;
  const d=r2(parseAmt(h.stmtCharges)-parseAmt(h.amount));
  return d>0.005 ? d : null;
};

// Money in, money out. Stored as a NUMBER of cents-free dollars (a float), but always
// parsed defensively: a bill whose amount is "" or garbage must read as 0, never NaN,
// or every total downstream becomes NaN.
function parseAmt(v){
  const n=typeof v==="number" ? v : parseFloat(String(v==null?"":v).replace(/[^0-9.\-]/g,""));
  return Number.isFinite(n) && n>0 ? n : 0;
}
function fmtMoney(n){
  const v=parseAmt(n);
  return "$"+v.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
}
// Compact money for the graph's month labels. These render at 8px in a bar that can be
// ~55px wide on an iPhone 14 Pro — fmtMoney's "$1,230.00" would not fit, and the cents
// are noise on a monthly total. Whole dollars; abbreviated past 10k so a mortgage month
// can't blow the column out.
function fmtMoneyShort(n){
  const v=Math.round(parseAmt(n));
  if(v>=10000) return "$"+(v/1000).toFixed(v>=100000?0:1).replace(/\.0$/,"")+"k";
  return "$"+v.toLocaleString();
}
// What an occurrence actually cost: the amount recorded when it was ticked paid,
// falling back to the series' expected amount if it hasn't been paid yet.
function occAmount(series,dateStr){
  const ex=(series.exceptions&&series.exceptions[dateStr])||{};
  if(ex.amount!=null) return parseAmt(ex.amount);
  // A BNPL plan's `amount` is the TOTAL, not what any one instalment costs. Without
  // this, every unpaid instalment would display the full $200 and the month's "due"
  // figure would be 4 x $200 = $800.
  if(isPlan(series)){
    const i=series.plan.dates.indexOf(dateStr);
    if(i>=0) return parseAmt((series.plan.amounts||[])[i] ?? (parseAmt(series.plan.total)/series.plan.count));
  }
  return parseAmt(series.amount);
}
// ── REPAIR: a series CUT IN HALF by "this and all future" *(v113)* ────────────────────
// Ending a repeat doesn't end the bill — it ends the SERIES. A new record gets created for
// the remainder, and now two records describe one bill. Mandy's Water: id 46 `recurEnd`
// 2026-05-11, id 47 `dueDate` 2026-05-11. One stops the day the other starts.
//
// This is NOT a duplicate, and DELETING EITHER HALF DESTROYS REAL PAYMENTS. 46 held
// February; 47 held May *and a receipt photo*. So they are MERGED, never deleted.
//
// THE TRAP: the two anchors can be days apart (46 paid on the 12th, 47 anchors the 11th).
// An exception keyed to a date the SURVIVING series never generates is a payment that
// exists in the file and RENDERS NOWHERE — materialize only ever looks at grid dates. So
// each carried-over payment is RE-KEYED onto the nearest date the survivor actually
// generates, and the survivor's anchor is walked back far enough to cover it.
//
// Pairs are only matched when the boundary is EXACT and cadence/category agree. Anything
// ambiguous is left alone — a repair that guesses is worse than no repair.
function findSplitPairs(tasks){
  const bills=tasks.filter(t=>isBill(t)&&!t.done);
  const pairs=[];
  bills.forEach(a=>{
    if(!a.recurEnd || a.recur==="none") return;
    bills.forEach(b=>{
      if(a===b || b.recurEnd) return;                        // survivor must be open-ended
      // BOUNDARY: EXACT **OR** ADJACENT *(v234)*. `recurEnd` is INCLUSIVE, so the
      // "this and future" split correctly writes the dead half's end as the day BEFORE
      // the survivor starts (`addDays(d,-1)`) — otherwise both halves would generate an
      // occurrence on the changeover date. This matcher demanded they be the SAME date,
      // so it never saw a pair produced by the app's own split path. Mandy's Spotify:
      // id 70 recurEnd 2026-07-19, id 81 dueDate 2026-07-20 — one day apart, invisible.
      // Adjacency is the ONLY relaxation: still same title, cadence and category, and
      // the survivor must still be open-ended. Anything else is left alone.
      if(b.dueDate!==a.recurEnd && b.dueDate!==addDays(a.recurEnd,1)) return;
      if(a.recur!==b.recur) return;                          // same cadence
      if((a.billCat||"")!==(b.billCat||"")) return;          // same category
      if((a.title||"").trim()!==(b.title||"").trim()) return;// same bill
      pairs.push({dead:a, live:b});
    });
  });
  return pairs;
}
function mergeSplitSeries(tasks, pair){
  const {dead,live}=pair;
  const step=RECUR_MONTHS[live.recur]||0;
  if(!step) return null;                                     // only month-stepped bills
  const carried=billHistory(dead).filter(h=>h.amount!=null || h.doneAt);
  if(!carried.length) return null;
  // `addMonths` is the ONLY correct stepper — it carries the series' ORIGINAL day-of-month
  // as an anchor so a short month can't permanently drag every later occurrence back a day
  // (v41). Reimplementing the arithmetic here is exactly how the anchor bug got in.
  const anchorDay=Number(live.dueDate.slice(8,10));
  const earliest=carried.map(h=>h.date).sort()[0];
  let anchor=live.dueDate, guard=0;
  while(anchor>earliest && guard++<600) anchor=addMonths(anchor,-step,anchorDay);
  const grid=[]; let d=anchor;
  for(let i=0;i<600 && d<=live.dueDate;i++){ grid.push(d); d=addMonths(d,step,anchorDay); }
  const ex={...(live.exceptions||{})};
  const moved=[];
  carried.forEach(h=>{
    // nearest generated date to the one it was actually paid against
    const near=grid.reduce((best,g)=>Math.abs(daysBetween(g,h.date))<Math.abs(daysBetween(best,h.date))?g:best, grid[0]);
    if(!near || ex[near]) return;                            // never clobber a real payment
    const src=(dead.exceptions&&dead.exceptions[h.date]) || {done:true,doneAt:dead.doneAt,amount:dead.amount,paidBy:dead.paidBy||null};
    ex[near]={...src};                                       // photo, amount, payer, all of it
    moved.push({from:h.date,to:near,amount:h.amount});
  });
  if(!moved.length) return null;
  const merged={...live, dueDate:anchor, exceptions:ex};
  delete merged.recurEnd;                                    // ABSENCE, not null (v107)
  return {merged, removeId:dead.id, moved};
}
// One-time REPAIR: un-ticking a bill used to write `amount:null` / `paidBy:null` into
// the occurrence's exception. materialize() spreads the exception OVER the series, so
// the null overwrote the bill's real amount instead of clearing it — permanently, for
// that occurrence. The row read $1,200 (occAmount falls back to the series) while the
// paid-prompt read 0.00 (it read occ.amount and got the null).
//
// Safe and unambiguous: a null in one of these slots is NEVER meaningful. It only ever
// meant "cleared", and "cleared" is now expressed by the key being ABSENT. So any null
// found here is the bug, and deleting it restores the fallback. Nothing is guessed.
// An occurrence marked BOTH paid and deleted *(v105)*.
//
// deleteTask used to merge `deleted:true` INTO the existing exception rather than
// replacing it, so deleting an occurrence that was already paid left both flags set.
// billHistory tested `.done` and never looked at `.deleted`, so the payment stayed in the
// spend graph, the monthly totals and the fairness split while the row vanished from the
// list. Mandy deleted a Stan payment and went on being charged for it in every number.
//
// The delete is what the user MEANT — a deleted occurrence does not exist, so it cannot
// have been paid. Strip the payment and leave a bare tombstone. The reverse (keeping the
// payment and dropping the delete) would resurrect rows they had explicitly removed.
function repairPaidDeleted(t){
  if(!t) return null;
  const ex=t.exceptions||{};
  let changed=false;
  const out={};
  Object.keys(ex).forEach(k=>{
    const e=ex[k];
    // A HAND-RECORDED STATEMENT IS THE EXCEPTION *(v296)*. `recorded` means this record
    // was typed into the statement form, which happens AFTER any delete on that date —
    // the write is newer than the tombstone, so the delete is no longer what the user
    // means. Stripping it here would destroy a statement rather than repair it. The
    // hb_stmtDelFix sweep clears the stale flag off these instead.
    if(e && e.deleted && e.recorded && e.done && e.amount!=null){ out[k]=e; }
    else if(e && e.deleted && (e.done || e.amount!=null || e.paidBy)){ out[k]={deleted:true}; changed=true; }
    else out[k]=e;
  });
  return changed ? out : null;
}
function repairNulledAmounts(t){
  if(!t || !t.exceptions) return null;
  let changed=false;
  const out={};
  Object.entries(t.exceptions).forEach(([k,e])=>{
    const c={...e};
    ["amount","paidBy","doneAt","award"].forEach(f=>{
      if(f in c && c[f]===null){ delete c[f]; changed=true; }
    });
    out[k]=c;
  });
  return changed ? out : null;
}
// Every PAID occurrence of a bill, newest first — this is the history.
function billHistory(series){
  const ex=series.exceptions||{};
  const out=[];
  // Card-ness computed ONCE and tagged onto every record, so spendYM can derive a
  // statement's month without a stored stmtYM or a migration having run *(v293)*.
  const _seriesIsCard=(series&&(series.billCat||"")===CARD_CAT);
  // A non-recurring bill keeps its state on the series itself, not in exceptions.
  // A PLAN IS THE EXCEPTION *(v266)*: it has recur:"none" but its paid instalments live in
  // exceptions, one per due date — exactly like a recurring series. Without this guard,
  // billHistory took the one-off branch, read series.done (always false for a plan) and
  // returned an EMPTY history, so a BNPL plan's paid instalments never appeared in Past
  // payments, the spend graph, or the fairness split. Same recur:"none"-but-multi-occurrence
  // blind spot fixed in the occurrence helpers (v264) and materialize (v265); billHistory
  // was the last reader still treating a plan as a one-off. Plans fall THROUGH to the
  // exceptions loop below.
  if((!series.recur||series.recur==="none") && !isPlan(series)){
    if(series.done) out.push({date:series.dueDate, amount:parseAmt(series.amount), doneAt:series.doneAt, paidYMD:(series.doneAt?toLocalYMD(new Date(series.doneAt)):series.dueDate), paidBy:series.paidBy||null, isCard:_seriesIsCard, stmtYM:series.stmtYM||null, stmtCharges:(series.stmtCharges!=null?series.stmtCharges:null), stmtFrom:series.stmtFrom||null, stmtTo:series.stmtTo||null});
    return out;
  }
  Object.keys(ex).forEach(d=>{
    // paidBy is null for anything paid BEFORE the field existed. Deliberately NOT
    // back-filled from `assignee` — that's who a bill is ASSIGNED to, not who paid
    // it, so guessing would make the fairness totals quietly wrong. Unattributed
    // payments are reported separately instead.
    // `date` = the DUE date (the exceptions key). `paidYMD` = the day the money
    // actually left, which is the one that matters for "what did we spend in July".
    // They differ whenever a payment is backdated, or simply ticked late. Falls back
    // to the due date for old rows with no doneAt.
    // A DELETED OCCURRENCE IS NOT A PAYMENT *(v105)*
    //
    // This tested `.done` alone. deleteTask used to merge `deleted:true` INTO the existing
    // exception, so deleting a paid occurrence left { done:true, deleted:true } — and this
    // line happily counted it. The row disappeared from the list while its money stayed in
    // the spend graph, the monthly totals and the fairness split. You deleted a bill and
    // went on paying for it in every number that mattered.
    //
    // deleteTask now writes a bare tombstone, so new data cannot reach that state. This
    // guard is for the records ALREADY carrying both flags — they exist, they are in the
    // wild, and without it they keep being counted forever.
    // stmtYM / stmtCharges / stmtFrom / stmtTo ride along so every reader can ask
    // spendYM()/spendAmt() without re-opening the exceptions map *(v291)*.
    if(ex[d]&&ex[d].done&&!ex[d].deleted) out.push({date:d, amount:occAmount(series,d), doneAt:ex[d].doneAt, paidYMD:(ex[d].doneAt?toLocalYMD(new Date(ex[d].doneAt)):d), paidBy:ex[d].paidBy||null, isCard:_seriesIsCard, stmtYM:ex[d].stmtYM||null, stmtCharges:(ex[d].stmtCharges!=null?ex[d].stmtCharges:null), stmtFrom:ex[d].stmtFrom||null, stmtTo:ex[d].stmtTo||null});
  });
  return out.sort((a,b)=>b.date.localeCompare(a.date));
}

// Who has actually paid what. A "split" payment counts half to each. Payments made
// before paidBy existed have no owner and are reported as `unknown` rather than
// being guessed at — a fairness number you can't trust is worse than none.
function fairness(bills, from){
  let her=0, him=0, unknown=0;
  bills.forEach(b=>billHistory(b).forEach(h=>{
    // Ranged by when it was PAID — "who paid what this year" means money that moved
    // this year, not bills that were due this year.
    if(from && (h.paidYMD||h.date) < from) return;   // ranged by REAL payment date — a statement's month does not move when money left *(v291)*
    if(h.paidBy==="her") her+=h.amount;
    else if(h.paidBy==="him") him+=h.amount;
    else if(h.paidBy==="split"){ her+=h.amount/2; him+=h.amount/2; }
    else unknown+=h.amount;
  }));
  const total=her+him;
  return {her, him, unknown, total,
          diff:Math.abs(her-him),
          ahead: her===him ? null : (her>him ? "her" : "him")};
}

// Reward-goal defaults: one shared household goal + a personal goal each.
// `claimed` = how many points have already been cashed in against this goal. Progress
// is (current - claimed), so claiming a 100-pt goal at 120 pts leaves you at 20/100 —
// the surplus carries over. Lifetime points are NEVER touched by a claim, so a reward
// can't cost you a level.
const DEFAULT_REWARDS = {
  shared: { target:100, treat:"Friday takeaway night", period:"lifetime", claimed:0 },
  her:    { target:60,  treat:"A lazy Sunday morning", period:"lifetime", claimed:0 },
  him:    { target:60,  treat:"Game night, his pick", period:"lifetime", claimed:0 },
};

// Category → gradient swatch + representative line icon (drawn as SVG paths below).
// Defaults; the live ROOM_META object below is mutated from saved state so
// categories can be renamed, recoloured, and added.
const DEFAULT_CATEGORIES = {
  Kitchen:      { grad:["#FFC93C","#FF8A00"], icon:"kitchen" },
  Bathroom:     { grad:["#38C6FF","#1E7BE0"], icon:"bathroom" },
  Garden:       { grad:["#6BE86B","#22B04A"], icon:"garden", outdoor:true },
  Bedroom:      { grad:["#D98AFF","#9A3CE0"], icon:"bedroom" },
  "Living Room":{ grad:["#FF9A62","#E0562E"], icon:"living" },
  Garage:       { grad:["#AEB6C4","#6A7488"], icon:"garage" },
  Laundry:      { grad:["#3FE0D0","#1E9E9E"], icon:"laundry" },
  Other:        { grad:["#C8BC9E","#8A7C5C"], icon:"other" },
};
// Live object — mutated in place so existing ROOM_META[...] references stay valid.
const ROOM_META = JSON.parse(JSON.stringify(DEFAULT_CATEGORIES));
function applyCategories(cats){
  Object.keys(ROOM_META).forEach(k=>{ delete ROOM_META[k]; });
  Object.assign(ROOM_META, cats);
}
// SINGLE SOURCE OF TRUTH for "what icon and colour does this task wear?".
//
// A bill keeps its `room` field (so it survives being switched back to a task),
// but a bill is NOT in the Kitchen — it must wear its BILL CATEGORY's icon and
// colour. Every renderer used to read ROOM_META[t.room] directly, so a Mortgage
// bill rendered with a Kitchen pot on a Kitchen gradient. There were 8 such
// sites; patching them one at a time is how one gets left behind. They all call
// this instead.
//
// Returns the ROOM_META shape ({grad:[from,to], icon}) either way, so callers
// need no special-casing — a bill's single `color` is widened into a gradient
// the same way eventGrad does it.
function taskMeta(t){
  if(isBill(t)){
    const bc = BILL_CATS[t&&t.billCat] || BILL_CATS.Other || DEFAULT_BILL_CATS.Other;
    return { grad:[bc.color, mixHex(bc.color,"#000",0.3)], icon:bc.icon, bill:true };
  }
  return ROOM_META[t&&t.room] || ROOM_META.Other;
}
// v271 · SINGLE SOURCE OF TRUTH for "what does this task's category chip SAY?".
//
// The twin of taskMeta(), for the WORD rather than the icon. A bill is a task under
// the hood so it carries a `room`, and `room` defaults to "Kitchen" — so a Mortgage
// bill rendered the chip "KITCHEN" while taskMeta() correctly drew the green Mortgage
// house beside it. Its real category is billCat.
//
// This was fixed ONCE (at the bills-list row builder) and the other five row builders
// were left reading t.room raw — the same "patch one site, leave seven behind" that
// taskMeta() exists to prevent. Every builder calls this instead.
function taskCatLabel(t){
  return isBill(t) ? ((t&&t.billCat)||"Other") : (t&&t.room);
}
// Icon library offered when creating/editing an EVENT category. Leads with the
// event-flavoured icons, then the full shared set. Excludes duplicates.

// ─── WEATHER ─────────────────────────────────────────────────────────────────
// Live forecast via Open-Meteo (free, no API key). Location is user-set; we
// default to Brisbane. A task/event/category flagged `outdoor` gets a rain
// warning when its date falls on a wet day, plus a suggested next dry day.
// Never blocks completion — purely advisory.

const DEFAULT_LOCATION = { name:"Brisbane", lat:-27.4698, lon:153.0251 };

// WMO weather-code → { label, wet, icon-key }. `wet` marks codes we treat as
// "don't do outdoor work" (drizzle/rain/showers/snow/thunder).
const WMO = {
  0:{l:"Clear",wet:false,i:"sun"}, 1:{l:"Mainly clear",wet:false,i:"sun"},
  2:{l:"Partly cloudy",wet:false,i:"cloudsun"}, 3:{l:"Overcast",wet:false,i:"cloud"},
  45:{l:"Fog",wet:false,i:"cloud"}, 48:{l:"Fog",wet:false,i:"cloud"},
  51:{l:"Light drizzle",wet:true,i:"rain"}, 53:{l:"Drizzle",wet:true,i:"rain"}, 55:{l:"Heavy drizzle",wet:true,i:"rain"},
  56:{l:"Freezing drizzle",wet:true,i:"rain"}, 57:{l:"Freezing drizzle",wet:true,i:"rain"},
  61:{l:"Light rain",wet:true,i:"rain"}, 63:{l:"Rain",wet:true,i:"rain"}, 65:{l:"Heavy rain",wet:true,i:"rain"},
  66:{l:"Freezing rain",wet:true,i:"rain"}, 67:{l:"Freezing rain",wet:true,i:"rain"},
  71:{l:"Light snow",wet:true,i:"snow"}, 73:{l:"Snow",wet:true,i:"snow"}, 75:{l:"Heavy snow",wet:true,i:"snow"}, 77:{l:"Snow grains",wet:true,i:"snow"},
  80:{l:"Showers",wet:true,i:"rain"}, 81:{l:"Showers",wet:true,i:"rain"}, 82:{l:"Violent showers",wet:true,i:"rain"},
  85:{l:"Snow showers",wet:true,i:"snow"}, 86:{l:"Snow showers",wet:true,i:"snow"},
  95:{l:"Thunderstorm",wet:true,i:"storm"}, 96:{l:"Thunderstorm",wet:true,i:"storm"}, 99:{l:"Thunderstorm",wet:true,i:"storm"},
};
function wmoInfo(code){ return WMO[code] || { l:"—", wet:false, i:"cloud" }; }

// A day is "wet" if the code is wet OR precipitation probability is high.
// Open-Meteo renamed `weathercode` -> `weather_code`. The URL asks for the NEW name, so
// the response carries the NEW name — but the code read the OLD one and got `undefined`.
// Accept BOTH, in one place, so a rename can never take the app down again.
function dailyCodes(daily){ return (daily && (daily.weather_code || daily.weathercode)) || null; }
function dailyProbs(daily){ return (daily && (daily.precipitation_probability_max)) || null; }

function dayIsWet(daily, idx){
  if(idx==null||idx<0) return false;
  const code = dailyCodes(daily)?.[idx];
  const prob = daily?.precipitation_probability_max?.[idx];
  if(code!=null && wmoInfo(code).wet) return true;
  if(typeof prob==="number" && prob>=60) return true;
  return false;
}

async function fetchForecast(lat, lon){
  const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}`
    +`&current=temperature_2m,weather_code`
    +`&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max`
    +`&timezone=auto&forecast_days=14`;
  const res=await fetch(url);
  if(!res.ok) throw new Error("weather fetch failed");
  return res.json();
}

// Given a forecast + a target date string, return advisory info for outdoor work.
function outdoorAdvice(forecast, dateStr, today){
  if(!forecast?.daily?.time) return null;
  const days=forecast.daily.time;
  const idx=days.indexOf(dateStr);
  if(idx<0) return null; // outside forecast window — no advice
  const wet=dayIsWet(forecast.daily, idx);
  // GUARDED. This bare index was the crash: `undefined[13]`, and the app never booted.
  const codes=dailyCodes(forecast.daily);
  const info=wmoInfo(codes?.[idx]);
  const prob=forecast.daily.precipitation_probability_max?.[idx];
  if(!wet) return { wet:false, label:info.l, iconKey:info.i, prob };
  // find next dry day at/after the target within the window
  let nextDry=null;
  for(let j=idx+1;j<days.length;j++){
    if(!dayIsWet(forecast.daily,j)){ nextDry=days[j]; break; }
  }
  return { wet:true, label:info.l, iconKey:info.i, prob, nextDry };
}

// Small weather glyphs (stroke=currentColor).
function WeatherIcon({ name, size=14 }){
  const p={fill:"none",stroke:"currentColor",strokeWidth:2,strokeLinecap:"round",strokeLinejoin:"round"};
  const g={
    sun:<><circle {...p} cx="12" cy="12" r="4"/><path {...p} d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6l1.4 1.4M17 17l1.4 1.4M18.4 5.6L17 7M7 17l-1.4 1.4"/></>,
    cloudsun:<><circle {...p} cx="8" cy="8" r="3"/><path {...p} d="M8 2v1M2 8h1M3.8 3.8l.7.7"/><path {...p} d="M17 18H7a4 4 0 0 1 0-8 5 5 0 0 1 9.6 1.4A3.5 3.5 0 0 1 17 18z"/></>,
    cloud:<path {...p} d="M17.5 19H7a4.5 4.5 0 0 1 0-9 5.5 5.5 0 0 1 10.6 1.6A3.5 3.5 0 0 1 17.5 19z"/>,
    rain:<><path {...p} d="M18 14.5A4 4 0 0 0 16 7h-1.3A6 6 0 1 0 5 12.5"/><line {...p} x1="8" y1="18" x2="8" y2="20"/><line {...p} x1="12" y1="18" x2="12" y2="21"/><line {...p} x1="16" y1="18" x2="16" y2="20"/></>,
    snow:<><path {...p} d="M18 13.5A4 4 0 0 0 16 6h-1.3A6 6 0 1 0 5 11.5"/><path {...p} d="M8 17v.01M12 18v.01M16 17v.01M10 20v.01M14 20v.01"/></>,
    storm:<><path {...p} d="M18 12.5A4 4 0 0 0 16 5h-1.3A6 6 0 1 0 5 10.5"/><path {...p} d="M12 12l-2 4h3l-2 4"/></>,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true">{g[name]||g.cloud}</svg>;
}

// Pretty short date e.g. "Sun 12 Jul"
function shortDate(ds){
  try{
    const d=new Date(ds+"T00:00:00");
    // THE YEAR IS NOT DECORATION *(v106)* — the same rule relLabel uses, for the same reason.
    // This printed day+month and never the year, so a task completed in November 2025 read
    // exactly like one completed last week. Composed by hand rather than by adding `year` to
    // the options bag: {weekday,day,month,year} picks a different en-AU skeleton and returns
    // "Sun, 12 July 2025" — comma, month spelled out — which would restyle every date in the
    // app, including those with no year at all. This keeps "Sun 12 Jul" and appends " 2025".
    const base=d.toLocaleDateString("en-AU",{weekday:"short",day:"numeric",month:"short"});
    return d.getFullYear()!==new Date().getFullYear() ? `${base} ${d.getFullYear()}` : base;
  }
  catch{ return ds; }
}


