// ONE SHARED ICON POOL for every category type (tasks, events, bills).
//
// There were two hard-coded subsets — CATEGORY_ICONS (43) and EVENT_ICON_LIBRARY (44) —
// and 12 drawable icons were in NEITHER: the bill icons. Drawable but unreachable. So the
// pools are now GROUPED VIEWS OF ICON_PATHS rather than independent lists: adding a path
// makes it selectable, and nothing can be stranded again.
//
// Strictly a superset of what was offered before (78 = 66 kept + 12 unlocked) — every
// icon that was pickable still is.
const ICON_GROUPS = [
  // NOTE ON `clock` *(v262)*: it is NOT listed here, and that is deliberate. `clock` and
  // `shift` draw near-identical circle-with-hands glyphs, and Mandy reported them as a
  // duplicate across two groups. Only `shift` is offered in the picker. `clock` is NOT
  // deleted from ICON_PATHS — it is the Appointment event category's icon, so removing the
  // path would repoint a live category. A group listing is a PICKER choice; the catalog is
  // the source of truth, and `iconGroupsWithRest` would otherwise sweep it into "More", so
  // it is named in an explicitly hidden list below.
  ["Bills & home",     ["bolt","waterdrop","flame","home","building","wifi","shield","bank","repeat","truck","card","bills","key"]],
  ["Rooms",            ["kitchen","bathroom","garden","bedroom","living","garage","laundry","window","fridge","bulb","other"]],
  ["Chores",           ["broom","spray","dishes","trash","vacuum","dusting","iron","hammer","paint","mower","water","cart","shopping"]],
  ["Outdoors & pets",  ["trees","flower","plant","sun","moon","cooling","pet","catface","paw","petbowl","fish","baby","tent","compass","pin","plane","takeoff"]],
  ["Celebrations",     ["rings","ring","cheers","cake","gift","balloon","hearts","heart","ticket","star"]],
  ["Food & social",    ["dining","cup","coffee","wine","users","bag"]],
  ["Health & self-care",["spa","pill","stethoscope","tooth","sleep","medical","cross","scissors"]],
  ["Work & leisure",   ["shift","briefcase","cap","book","booklet","music","mic","film","camera","palette","dumbbell","ball","run","car","calendar","phone"]],
];
// Flattened, de-duplicated, and BACKSTOPPED: any icon in ICON_PATHS that a group forgot is
// appended rather than silently lost. The grouping is a presentation choice; the pool is
// the source of truth.
const CATEGORY_ICONS = (()=>{
  const grouped=ICON_GROUPS.flatMap(([,list])=>list);
  const seen=new Set();
  const out=grouped.filter(i=>ICON_PATHS[i]&&!seen.has(i)&&seen.add(i));
  Object.keys(ICON_PATHS).forEach(i=>{ if(!seen.has(i)){ seen.add(i); out.push(i); } });
  return out;
})();
const EVENT_ICON_LIBRARY = CATEGORY_ICONS;   // same pool — kept as an alias for call sites
// ICON_GROUPS as the picker draws it: every group filtered to icons that actually EXIST,
// plus a trailing "More" for anything in ICON_PATHS that no group lists. Same backstop
// contract as CATEGORY_ICONS above — the POOL is the source of truth and the grouping is a
// presentation choice, so a typo'd or forgotten key degrades to an extra heading rather
// than silently removing an icon from the picker.
// RETIRED FROM THE PICKER, KEPT IN THE CATALOG *(v262)*.
// Both draw a glyph that duplicates one already offered — `clock` is a circle-with-hands
// like `shift`, `drop` is a plain teardrop superseded by `waterdrop`. Neither can be
// deleted from ICON_PATHS: `clock` is the Appointment event category's icon and `drop` was
// the Water bill category's, so removing the path would blank a live category rather than
// tidy a list. They stay drawable and simply are not offered.
//
// They must ALSO be named here rather than merely left out of ICON_GROUPS, because
// iconGroupsWithRest sweeps anything ungrouped into a trailing "More" — the backstop that
// stops a typo stranding an icon would otherwise hand these straight back to the picker.
const ICONS_RETIRED = new Set(["clock","drop"]);
function iconGroupsWithRest(){
  const seen=new Set(ICONS_RETIRED);
  const out=ICON_GROUPS.map(([label,list])=>{
    const keep=list.filter(i=>ICON_PATHS[i]&&!seen.has(i)&&seen.add(i));
    return [label,keep];
  }).filter(([,l])=>l.length);
  const rest=Object.keys(ICON_PATHS).filter(i=>!seen.has(i));
  if(rest.length) out.push(["More",rest]);
  return out;
}
function RoomIcon({ name, size=24 }) {
  const inner = ICON_PATHS[name] || ICON_PATHS.other;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.7} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" dangerouslySetInnerHTML={{__html: inner}}/>
  );
}

// Priority scale (high → low). `noBadge:true` means the tag is hidden entirely
// on cards/lists. Stored as the numeric `value`; higher sorts first.
// "High" uses a fixed warm orange; "Low" uses a fixed blue so the ramp stays
// readable regardless of the theme accent.
// `short` is ONLY for the form's one-row picker, where five buttons share a phone width.
// Badges and lists keep `label` — "Med" on a task card would read as an abbreviation for
// no reason. Only Medium needs one; the rest already fit.
const PRIORITIES = [
  { label:"Urgent", short:"Urgent", value:5, color:C.urgent, soft:C.urgentSoft },
  { label:"High",   short:"High",   value:4, color:"#FF9A62", soft:"rgba(255,154,98,0.16)" },
  { label:"Medium", short:"Med",    value:3, color:C.medium, soft:C.mediumSoft },
  { label:"Low",    short:"Low",    value:2, color:C.him,    soft:C.himSoft },
  { label:"None",   short:"None",   value:1, color:C.inkMute, soft:C.pageWarm, noBadge:true },
];

// Person colours are stored as their Bold-mode value. In Sleek (dark) those
// mid-tone hexes go muddy on the near-black page, so we lift saturation+lightness
// at RENDER time only (storage is untouched, Bold is unaffected). One chokepoint
// so Her/Him read consistently everywhere.
function personColor(hex){
  if(!hex||C.mood!=="sleek") return hex;
  const h=hex.replace('#','');
  if(h.length<6) return hex;
  let r=parseInt(h.slice(0,2),16)/255,g=parseInt(h.slice(2,4),16)/255,b=parseInt(h.slice(4,6),16)/255;
  const max=Math.max(r,g,b),min=Math.min(r,g,b);let hh,s,l=(max+min)/2;
  if(max===min){hh=s=0;}else{const d=max-min;s=l>0.5?d/(2-max-min):d/(max+min);
    hh=max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4;hh/=6;}
  const S=Math.min(s*100+12,90), L=Math.min(l*100+20,72);
  return hslToHex(hh*360, Math.round(S), Math.round(L));
}

// Assignee display helpers — handle solo (her/him) and shared (both).
// An UNSET assignee is now legal (v110: nothing is preselected), so both helpers must
// answer for "" without throwing. "Unassigned" is a real state and reads as one.
function assigneeName(assignee, people){ if(!assignee) return "Unassigned"; return assignee==="both" ? "Both" : (people[assignee]?.name || assignee); }
// MUST WE ASK WHO PAID? *(v120)*
//
// The bug this closes: the who-paid prompt fired on `shared`, which is `assignee==="both"`.
// An UNASSIGNED bill is not "both" — so it never asked, and `toggleDone` fell through to
// `paidBy: (pointsTo || occ.assignee)`, which for a falsy assignee is **undefined**. The
// payment saved with NO PAYER: it read "Paid 8 Jul" with no name and contributed nothing to
// fairness. Silently, and only on the manual tick — autopay already wrote `assignee||"both"`.
//
// "Both" and "unassigned" are DIFFERENT FACTS but they ask the SAME QUESTION: the app cannot
// name the payer from the record alone, so a human must. `shared` answers "who gets the
// POINTS" (a task question, where unassigned genuinely means nobody). This answers "who paid
// the MONEY". They are not the same predicate and must not share one.
function needsPayer(assignee){ return !assignee || assignee==="both"; }
// The payer to RECORD when the prompt didn't run (auto-pay, who-pays off, a legacy record).
// Unassigned falls to "split" for exactly the reason auto-pay already did: the money left an
// account, and refusing to record it loses the payment entirely — worse than splitting it.
function fallbackPayer(assignee){ return needsPayer(assignee) ? "split" : assignee; }
// ─── v206 · PAYER LABEL — THE one place a stored payer becomes text ───────────
// `people` has exactly two keys (her/him). "split" is a legitimate third value that
// names no single person. ANYTHING ELSE is not a person: "both" was written by the
// autopay path (v206 bug), and older/hand-edited records can hold anything at all.
//
// Reading `people[paidBy].name` on such a value returns undefined and throws, which
// killed the ENTIRE Bills tab — one bad row took down every row. A payer label is
// cosmetic; it must never be able to do that. An unknown payer degrades to "Split",
// which is also the truthful reading of "shared, nobody named".
//
// This is the READ guard. The WRITE side (autopay) is fixed separately at source —
// but the guard has to exist regardless, because data already in the wild holds
// "both" and no write-side fix can reach records that are already saved.
function payerLabel(paidBy, people){
  if(!paidBy) return "";                       // never recorded — say nothing
  if(paidBy==="split") return "Split";
  const p=people&&people[paidBy];
  return (p&&p.name) ? p.name : "Split";       // unknown key → shared, never a crash
}
function assigneeColor(assignee, people){ if(!assignee) return C.inkMute; return assignee==="both" ? C.low : personColor(people[assignee]?.color || C.inkMute); }
// Renders the assignee chip(s) for a task/event. A "both" item shows a single
// neutral "Both" chip, or — when the "Name shared tasks" setting is on — one
// badge per person in their own colour. `size` picks the card (10px) vs the
// tighter agenda-row (9px) scale.
//
// A COMPLETED shared task shows only WHO WAS AWARDED *(v147)*. A "both" task, once done,
// gave its points to one person (or was split). Showing both names afterwards misreports
// who actually earned it. `award` is the stored {her,him} from completion: if exactly one
// side is positive, that person earned it alone and is the only badge. A genuine SPLIT
// (both positive) still shows both, because both did earn. When there's nothing to read
// (no-points task, or award absent), fall back to the assignment — better both than wrong.
function awardedSolo(task){
  if(!task || !task.done) return null;
  // A resolved occurrence has already had materialize() spread its exception over the
  // series ({...series, ...ex}), so `award` and `paidBy` live directly on `task` — no need
  // to reach back into exceptions[date].
  // Bills carry the owner in paidBy; a solo payer narrows the badge the same way.
  if(isBill(task) && task.paidBy && task.paidBy!=="split") return task.paidBy;
  const a = task.award;
  if(!a) return null;
  const her=a.her>0, him=a.him>0;
  if(her && !him) return "her";
  if(him && !her) return "him";
  return null;   // split, or zero-point — leave the assignment badges as they are
}
function AssigneeBadges({assignee,people,size="card",task=null}){
  // v274 · Compact card sizing. The "card" size drops to 9/2px6px to match the smaller
  // title and tile; "row" (the dashboard agenda) is unchanged — it was already compact.
  const fs = size==="row" ? 9 : 9;
  const pad = size==="row" ? "3px 8px" : "2px 6px";
  const chip=(label,color,key)=>(
    <span key={key} className="sans" style={{fontSize:fs,fontWeight:600,letterSpacing:0.3,background:softTint(color),color,padding:pad,borderRadius:6,whiteSpace:"nowrap"}}>{label}</span>
  );
  // Completed shared task awarded to ONE person -> show only that person.
  const solo = assignee==="both" ? awardedSolo(task) : null;
  if(solo==="her") return chip(people.her.name, personColor(people.her.color), "her");
  if(solo==="him") return chip(people.him.name, personColor(people.him.color), "him");
  if(assignee==="both"&&SHARED.named){
    return(<>
      {chip(people.her.name, personColor(people.her.color), "her")}
      {chip(people.him.name, personColor(people.him.color), "him")}
    </>);
  }
  return chip(assigneeName(assignee,people), assigneeColor(assignee,people), "one");
}
const DAYS = ["S","M","T","W","T","F","S"];
const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
// ONE reserved width, shared by the month and week headers, so the ‹ › arrows sit at
// the SAME x-position in both — nothing jumps when you toggle between views. Sized to
// the widest label either can show: "September 2026" (~148px in the Georgia fallback).
//
// This is why the week header omits the year: "28 Sep – 4 Oct 2026" is ~182px and
// would blow the shared box, forcing it to 190px and pushing the MONTH arrows back
// out. Without the year it's ~141px and fits. The week view lists seven dated rows
// underneath and the month view still shows the year, so it's the least load-bearing
// thing in that header.
const CAL_LABEL_W = 150;

// ── SPECTRUM PICKER RANGE ─────────────────────────────────────────────────────
// Was min=25 max=80 on lightness, with saturation HARD-CODED to 72 and no slider.
// That is a narrow box in the middle of the colour space: no pastels, no deep tones,
// and — because saturation never moved — no muted colours and no grey at all.
// Not 0/100: a pure-black or pure-white category has no hue left to identify it by,
// and every chip, tile and dot in the app is drawn FROM that hue.
const SPEC_L_MIN = 8;
const SPEC_L_MAX = 92;

// ── MULTI-DAY EVENTS *(v220)* ────────────────────────────────────────────────
// STORED AS A LENGTH, NEVER AS AN ABSOLUTE END DATE.
//
// A repeating event can also span days — a weekend away every month. If the record held
// `spanEnd:"2026-08-16"`, the SECOND occurrence would still claim to end in August. The
// span is therefore a COUNT of days including the first, and each occurrence derives its
// own end from its own start.
//
// This also means materialize gets per-occurrence spans for free: `exceptions[date]` can
// carry its own `spanDays`, and the existing `{...series, ...ex}` spread applies it to
// that occurrence alone. Storing an end date would have needed a parallel mechanism.
//
// ABSENCE IS A VALUE: a one-day event has NO spanDays key at all, not `spanDays:1`.
const CAL_SPAN_H = 12;    // px. Height of one span lane in a month cell, incl. its gap.
function spanDaysOf(ev){
  if(!ev) return 1;
  const n=Number(ev.spanDays);
  // Anything absent, unparseable or <1 is a single day. Math.max floors it rather than
  // rejecting, so a corrupt 0 or -3 degrades to a normal event instead of vanishing.
  return Number.isFinite(n) ? Math.max(1, Math.floor(n)) : 1;
}
function isSpan(ev){ return spanDaysOf(ev)>1; }

// ── ALL-DAY EVENTS *(v230)* ──────────────────────────────────────────────────
// A timeless event ALREADY worked before this: it saved, rendered and spanned. What was
// missing was INTENT. `isAllDay` reads a STORED FLAG and never infers from an empty time,
// because inferring would silently reclassify every timeless event already in the file —
// a note with no time is not the same thing as a birthday.
function isAllDay(ev){ return !!(ev && ev.allDay); }

