function SpanBand({ev,dateStr,color,onEdit,onEditDayNote}){
  const {st,total,n,endYMD}=spanBandInfo(ev,dateStr);
  const pips=[];
  for(let i=1;i<=total;i++) pips.push(i<=n);
  // v230 · the note for THIS day of the trip. Read through the choke point, at the CURRENT
  // day number — a note keyed past the end of a shortened trip is simply not found here,
  // which is exactly what makes shortening non-destructive.
  const note=dayNoteFor(ev,n);
  return(
    <div onClick={onEdit} className="sans"
      style={{border:`1px solid ${C.ruleSoft}`,borderLeft:`3px solid ${color}`,
        borderRadius:12,padding:"9px 12px",marginBottom:7,background:C.card,
        cursor:onEdit?"pointer":"default",boxShadow:C.shadowSm}}>
      <div style={{display:"flex",alignItems:"center",gap:6,minWidth:0}}>
        <span style={{fontSize:13,fontWeight:600,color:C.ink,whiteSpace:"nowrap",
          overflow:"hidden",textOverflow:"ellipsis"}}>{dayOffTitle(ev)}</span>
      </div>
      {/* v231 · META LINE, BUILT NOT FIXED. Day 1 used to sit in the events list where it
          showed its start time; now that it is a band, that time has to live here or it is
          simply lost. The time shows on the FIRST day ONLY — a 7am start is a fact about
          the day the trip begins, not about day 3 of it. The place shows on EVERY day: it
          is where you ARE for the whole span, and is the thing worth repeating.
          Joined with the same " · " separator the event rows use. */}
      <div style={{fontSize:10.5,color:C.inkMute,marginTop:3}}>
        {[`${shortDate(st)} – ${shortDate(endYMD)}`,
          `day ${n} of ${total}`,
          ...(n===1 && ev.time && !isAllDay(ev) ? [`from ${fmtTime(ev.time)}`] : []),
          ...(ev.place ? [ev.place] : [])].join(" · ")}
      </div>
      <div style={{display:"flex",gap:3,marginTop:7}}>
        {pips.map((on,i)=>(
          <span key={i} style={{height:3,flex:1,borderRadius:2,
            background:on?color:C.rule}}/>
        ))}
      </div>
      {/* v230 · PER-DAY NOTE, always visible (Mandy chose A). stopPropagation because the
          band itself opens the EVENT editor — tapping the note must open the NOTE. */}
      {onEditDayNote&&(
        note ? (
          <div onClick={(e)=>{e.stopPropagation();onEditDayNote(ev,n);}}
            style={{marginTop:8,padding:"8px 10px",borderRadius:9,background:C.pageWarm,
              borderLeft:`2px solid ${C.inkFaint}`,fontSize:11.5,color:C.inkSoft,
              lineHeight:1.45,cursor:"pointer",whiteSpace:"pre-wrap"}}>{note}</div>
        ) : (
          <button type="button" onClick={(e)=>{e.stopPropagation();onEditDayNote(ev,n);}}
            className="sans"
            style={{display:"inline-flex",alignItems:"center",gap:5,marginTop:8,
              padding:"6px 10px",borderRadius:9,border:`1px solid ${C.rule}`,
              background:C.pageWarm,color:C.inkSoft,fontSize:11,fontWeight:600,cursor:"pointer"}}>
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              strokeWidth="2.6" strokeLinecap="round"><path d="M12 5v14M5 12h14"/></svg>
            Note for day {n}
          </button>
        )
      )}
    </div>
  );
}

// v230 · DAY NOTE SHEET. Defined at MODULE SCOPE, never nested in a render body: a nested
// component is a NEW type on every render, so React unmounts and remounts the textarea and
// the caret is lost mid-typing. The documented rule, and it bites hardest on a textarea.
function DayNoteSheet({ev,n,total,dateStr,color,onSave,onClose}){
  // A full-screen overlay MUST lock the body, or the day sheet keeps scrolling behind the
  // scrim while the keyboard is up. probe-scrolllock caught this omission.
  useScrollLock();
  const [text,setText]=useState(()=>dayNoteFor(ev,n));
  return(
    <div onClick={onClose} className="hb-scrim" style={{position:"fixed",inset:0,zIndex:Z_EDITOR,background:SCRIM_DIM,
      display:"flex",alignItems:"flex-end",justifyContent:"center"}}>
      <div onClick={(e)=>e.stopPropagation()} className="sans"
        style={{width:"100%",maxWidth:480,background:C.card,borderTopLeftRadius:20,
          borderTopRightRadius:20,padding:"18px 16px calc(18px + env(safe-area-inset-bottom))",
          borderTop:`3px solid ${color||C.accent}`}}>
        <h3 className="serif" style={{fontSize:17,color:C.ink,margin:0}}>Day {n} note</h3>
        <p style={{fontSize:11,color:C.inkMute,margin:"2px 0 12px"}}>
          {dayOffTitle(ev)} · {shortDate(dateStr)} · day {n} of {total}
        </p>
        <textarea value={text} onChange={(e)=>setText(e.target.value)} autoFocus
          placeholder="What is happening on this day?"
          style={{width:"100%",minHeight:96,padding:"11px 12px",borderRadius:11,
            border:`1px solid ${C.rule}`,background:C.pageWarm,color:C.ink,
            fontFamily:"'Roboto Condensed',sans-serif",fontSize:13,resize:"vertical",boxSizing:"border-box"}}/>
        <div style={{display:"flex",gap:8,marginTop:11}}>
          <button type="button" onClick={onClose} className="sans"
            style={{flex:1,padding:13,borderRadius:11,border:`1px solid ${C.rule}`,
              background:C.pageWarm,color:C.inkSoft,fontSize:13,fontWeight:700,cursor:"pointer"}}>Cancel</button>
          <button type="button" onClick={()=>onSave(text)} className="sans"
            style={{flex:1,padding:13,borderRadius:11,border:"none",
              background:C.accent,color:C.onAccent,fontSize:13,fontWeight:700,cursor:"pointer"}}>Save</button>
        </div>
      </div>
    </div>
  );
}
function spanSegments(occs, gridStartYMD, rowCount){
  const segs=[];
  // Lane bookkeeping is per ROW: lanes[row] is an array of the last column each lane
  // reaches. A segment takes the FIRST lane whose previous occupant has already ended,
  // so two spans that never overlap share lane 0 instead of stacking pointlessly.
  const lanes=[];
  const idxOf=(ymd)=>daysBetween(gridStartYMD, ymd);
  // Longest first. A short span slotted into lane 0 ahead of a long one would push the
  // long one down on every row it touches, which reads as a staircase rather than a bar.
  const sorted=occs.slice().sort((a,b)=>{
    const d=spanDaysOf(b)-spanDaysOf(a);
    return d!==0 ? d : String(a._occDate||a.date).localeCompare(String(b._occDate||b.date));
  });
  sorted.forEach(o=>{
    const startYMD=o._occDate||o.date;
    if(!startYMD) return;
    const days=spanDaysOf(o);
    if(days<=1) return;                         // not a span; drawn as an ordinary chip
    const endYMD=spanEndFor(o,startYMD);
    // Clip to the visible grid. A span starting in the previous month must still draw
    // its tail, so the start index is allowed to go negative before clamping.
    let a=idxOf(startYMD), b=idxOf(endYMD);
    const last=rowCount*7-1;
    if(b<0||a>last) return;                     // entirely outside the grid
    const clipL=a<0, clipR=b>last;
    if(a<0) a=0;
    if(b>last) b=last;
    for(let i=a;i<=b;){
      const row=Math.floor(i/7);
      const col=i%7;
      const rowEnd=row*7+6;
      const segEnd=Math.min(b,rowEnd);
      const len=segEnd-i+1;
      lanes[row]=lanes[row]||[];
      let lane=0;
      // First lane free for the WHOLE width of this segment.
      while(lanes[row][lane]!=null && lanes[row][lane]>=col) lane++;
      lanes[row][lane]=col+len-1;
      segs.push({
        key:(o._seriesId||o.id)+"@"+startYMD+"#"+row,
        row, col, len, lane,
        title:o.title||"",
        color:(EVENT_CATS[o.category]||EVENT_CATS.Other).color,
        // contL/contR say "this bar is CUT here, it did not begin/end here" — the
        // renderer squares that edge and drops the accent border, so a week viewed on
        // its own can tell a real start from a continuation.
        contL:(i>a)||clipL,
        contR:(segEnd<b)||clipR,
        startYMD, endYMD,
        time:o.time||null, end:o.end||null,
      });
      i=segEnd+1;
    }
  });
  // How many lanes each row actually needs — the cell reserves exactly this much and
  // no more, so a month with no spans loses no height at all.
  const laneCount=[];
  for(let r=0;r<rowCount;r++) laneCount[r]=(lanes[r]||[]).length;
  return {segs, laneCount};
}

// ── CALENDAR CELL GEOMETRY ────────────────────────────────────────────────────
// ONE source of truth. chipMax is DERIVED by measuring the room a week-row actually has
// and dividing by CAL_CHIP_H — so if these numbers and the rendered CSS ever disagree,
// the count is wrong and days silently overflow or waste space. Every one of them is used
// in BOTH the measurement and the render; don't hard-code them in either place.
const CAL_CHIP_FS   = 8;      // px. Was 7.2 — below what's readable at arm's length.
const CAL_CHIP_LH   = 1.15;   // was 1.3
const CAL_CHIP_PAD  = 1.25;   // vertical padding. 2 → 1.5 → 1.25
const CAL_CHIP_MT   = 1;      // gap between chips. 2 → 1.5 → 1
const CAL_CHIP_PX   = 2.5;    // HORIZONTAL padding. 3.5 → 2.5: the chip's left/right buffer
                              // is 7px of the ~48px a chip has, and every px of it is a px
                              // the title doesn't get. Worth ~0.5 of a character per line.
// 1 + 1.25*2 + 8*1.15 = 12.7px. It was 16.4px before any of this. The FONT GOT BIGGER
// (7.2 → 8) while the chip got SHORTER — all of it came out of padding and leading.
const CAL_CHIP_H    = CAL_CHIP_MT + CAL_CHIP_PAD*2 + CAL_CHIP_FS*CAL_CHIP_LH;
// FONT WEIGHT 500, not 700. The chips are already colour-coded, tinted, AND carry a coloured
// left border — bold is buying no legibility here, and at 8px a bold face costs ~1.5
// characters of line width. With -0.2px tracking that's ~10.5 chars/line instead of ~9.2.
const CAL_CHIP_FW   = 500;
const CAL_CHIP_LS   = -0.2;   // letter-spacing
const CAL_DAYNUM_H  = 15;     // the date number line
const CAL_CELL_PAD  = 5;      // cell padding, top + bottom
const CAL_ROW_GAP   = 2;      // grid gap between week rows
// MUST match the nav's real height (see the paddingBottom on the page root). chipMax is
// derived by measuring the room BELOW the grid, and this is what it subtracts — leave it
// stale after the nav grows and the calendar quietly reports one chip too many, which
// overflows the last week-row off the screen.
const CAL_NAV_H     = 72;     // nav content (60) + breathing room; the inset is on top

function todayStr(){
  // Local calendar date (not UTC). toISOString() returns UTC, which rolls the
  // date a day early/late for non-UTC timezones — the cause of "yesterday's"
  // items appearing. Build YYYY-MM-DD from local components instead.
  const d=new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
function getDaysInMonth(y,m){ return new Date(y,m+1,0).getDate(); }
function getFirstDay(y,m){ return new Date(y,m,1).getDay(); }
function relLabel(d,t){
  const a=new Date(d+"T00:00:00"),b=new Date(t+"T00:00:00");
  const diff=Math.round((a-b)/86400000);
  if(diff<0) return `${Math.abs(diff)}d overdue`;
  if(diff===0) return "Today";
  if(diff===1) return "Tomorrow";
  if(diff<7) return a.toLocaleDateString("en-AU",{weekday:"short"});
  // THE YEAR IS NOT DECORATION *(v106)*
  //
  // This printed day+month and NEVER the year. Mandy paid her yearly home insurance (due
  // 7 Jan 2026); the series correctly rolled forward to 7 Jan 2027 — and the new occurrence
  // rendered as "Due 7 Jan", character-for-character identical to the one she had just paid.
  // The bill looked STUCK in the Later bucket. The payment had saved perfectly; the label
  // simply refused to say WHICH January it meant. Nothing was wrong with the data — a
  // formatter that hides the year turns a correct roll-forward into a bug report.
  //
  // COMPOSED, NOT SWITCHED ON IN THE OPTIONS BAG. Passing {day,month,year} to
  // toLocaleDateString selects a DIFFERENT en-AU skeleton than {day,month} does — it spells
  // the month out and adds punctuation. So switching `year` on would silently restyle EVERY
  // date, including the ones that print no year at all. Building the string by hand keeps
  // "7 Jan" exactly as it has always been and merely appends " 2027".
  //
  // Compared against TODAY'S CALENDAR YEAR (b, already passed in), not a rolling 12 months:
  // the question is "which January", and a rolling window would still print a bare "7 Jan"
  // for a date 11 months out that lands in the next year. Same rule as shortDate, so the two
  // cannot drift apart again.
  const base=a.toLocaleDateString("en-AU",{day:"numeric",month:"short"});
  return a.getFullYear()!==b.getFullYear() ? `${base} ${a.getFullYear()}` : base;
}
// How LATE something is, in words. Days under 60; months beyond that; years beyond 12.
//
// "187d overdue" is precise and means nothing at a glance — you have to do the division
// yourself to feel it. Mandy's home insurance sat 187 days unpaid and read as calmly as a
// bill due next week. Past a couple of months the unit has to change or the number stops
// landing.
//
// Months are counted as WHOLE CALENDAR MONTHS, never days/30: 365/30 is 12.2, so a bill
// exactly one year old would read "12 months late" instead of "1 year late", and every
// long-overdue figure would be quietly wrong by a few percent.
//
// Returns null when nothing is late, so callers can render the badge conditionally on it.
function lateLabel(due, today){
  if(!due || !today) return null;
  const a=new Date(due+"T00:00:00"), b=new Date(today+"T00:00:00");
  const days=Math.round((b-a)/86400000);
  if(days<=0) return null;
  if(days<60) return `${days}d overdue`;
  let m=(b.getFullYear()-a.getFullYear())*12 + (b.getMonth()-a.getMonth());
  if(b.getDate()<a.getDate()) m--;   // the current month isn't complete yet
  if(m<1) m=1;
  if(m>=12){
    const y=Math.floor(m/12), rem=m%12;
    if(rem===0) return y===1 ? "1 year late" : `${y} years late`;
    return y===1 ? `1 yr ${rem}mo late` : `${y}yr ${rem}mo late`;
  }
  return m===1 ? "1 month late" : `${m} months late`;
}
function greeting(){
  const h=new Date().getHours();
  if(h<12) return "Good morning";
  if(h<17) return "Good afternoon";
  return "Good evening";
}

let _id=20; const uid=()=>++_id; const seedUid=(n)=>{ if(n>_id) _id=n; };
// v165 · Overtime has its own id space so it can NEVER collide with task ids.
// The shared `uid` counter resets to 20 on every reload and was only reseeded
// from hb_tasks — a freshly logged OT entry then reused a low id already held by
// another OT row, and saveOT's id-match rewrote every matching row ("edit one OT
// changes all OT"). Own counter + reseed-from-storage below fixes it for good.
let _otid=400; const otuid=()=>++_otid; const seedOtid=(n)=>{ if(n>_otid) _otid=n; };

const NAG_LINES=["A gentle nudge from your love","Still waiting on this one","You've got this","Not nagging — just reminding","The house won't do it itself","You're wonderful when you help"];

// Completion celebration — random stamp phrase + random exit animation.
const DONE_PHRASES=["Good job!","Nice one!","Boom! Done","Legend","Smashed it","Tidy!","Well done","One less!","Crushed it","Look at you","You're the best Bink!","Bestest Binky!"];
// Ticked AFTER the due date. The tier escalates with HOW late, but a line is then picked
// at random from WITHIN that tier — so it never says the same words at you two days
// running. Colour never changes: done is done, and the stamp stays green.
// Bills tick through this same path and deliberately share these lines.
const LATE_PHRASES={
  soft: ["Better late than never","Late, but done","Got there in the end","Fashionably late","Close enough!"],
  wry:  ["Better late than never","Only a week behind","It waited. Patiently.","Slow, but sure","Worth the wait?"],
  dry:  ["Finally.","It had almost given up","Better late than never — much later","Archaeology, at this point","A historic moment"],
};
const DONE_EXITS=["swipeR","swipeL","collapse","zoom","fall","lift"];
// `due` and `today` are both local YMD strings — never Date objects, never toISOString.
// A plain string compare is enough to know it's late; daysBetween gives the tier.
function latePool(due,today){
  if(!due||!today||due>=today) return null;
  const late=daysBetween(due,today);
  if(late<=0) return null;
  if(late<=2) return LATE_PHRASES.soft;
  if(late<=6) return LATE_PHRASES.wry;
  return LATE_PHRASES.dry;
}
const pickDone=(due,today)=>{
  const pool=latePool(due,today)||DONE_PHRASES;
  return {phrase:pool[Math.floor(Math.random()*pool.length)],exit:DONE_EXITS[Math.floor(Math.random()*DONE_EXITS.length)]};
};

