// ─── EVENTS ──────────────────────────────────────────────────────────────────
// Event categories: colour + soft fill + line icon key (drawn in EventIcon).
// Event categories: colour + line icon key. DEFAULT_EVENT_CATS seed the live
// EVENT_CATS object (mutated by applyEventCats from persisted state), mirroring
// the task-category system. Icons come from the shared ICON_PATHS library, so
// custom categories can pick any of the 43 icons. `custom:true` marks user-made
// ones (deletable/editable); built-ins are fixed. Shift is special (see below).
const DEFAULT_EVENT_CATS = {
  Date:        { color:"#E85D9E", icon:"heart" },
  Sport:       { color:"#57D964", icon:"ball" },
  Social:      { color:"#F0A93C", icon:"cup" },
  Appointment: { color:"#4FA3E8", icon:"clock" },
  Family:      { color:"#FF6B5C", icon:"users" },
  Travel:      { color:"#38BDF8", icon:"car" },
  Health:      { color:"#34D399", icon:"heart" },
  Birthday:    { color:"#F472B6", icon:"gift" },
  Holiday:     { color:"#FBBF24", icon:"sun" },
  Music:       { color:"#A78BFA", icon:"music" },
  Dinner:      { color:"#FB923C", icon:"dining" },
  Errand:      { color:"#60A5FA", icon:"cart" },
  Reward:      { color:"#E0B84A", icon:"gift" },    // earned treat — gold, created by claiming a goal
  Shift:       { color:"#B38BFF", icon:"shift" },   // work shift — violet, distinct from all accents
  Other:       { color:"#B0A48A", icon:"star" },
};
const EVENT_CATS = JSON.parse(JSON.stringify(DEFAULT_EVENT_CATS));
// ── v233 · A NAMED CATEGORY MAY NOT EXIST ────────────────────────────────────
// Every event category except Shift and Other is RENAMEABLE and DELETABLE from settings,
// and applyEventCats DELETES any category the person no longer has. So reading
// `EVENT_CATS.Date.color` directly is reading `.color` off undefined the moment they
// rename "Date" — which is exactly the crash reported from the phone: the add screen
// died with "Cannot read properties of undefined (reading 'color')".
//
// This is the choke point for that read. It falls back to the DEFAULT for the category
// (so the colour stays recognisable if it still exists in defaults), then to Other, then
// to a literal, so it can never throw whatever the person has done to their categories.
function catColor(name, fallback){
  const c = EVENT_CATS[name] || DEFAULT_EVENT_CATS[name] || EVENT_CATS.Other;
  return (c && c.color) || fallback || "#8A93A8";
}
function applyEventCats(cats){
  Object.keys(EVENT_CATS).forEach(k=>{ if(!cats[k]) delete EVENT_CATS[k]; });
  Object.entries(cats).forEach(([k,v])=>{ EVENT_CATS[k]=v; });
  // Shift + Other are always present as fallbacks.
  if(!EVENT_CATS.Shift) EVENT_CATS.Shift=DEFAULT_EVENT_CATS.Shift;
  if(!EVENT_CATS.Other) EVENT_CATS.Other=DEFAULT_EVENT_CATS.Other;
}
// Two-stop gradient for an event category. `color` remains the primary hue (used
// for chips/borders); the "To" stop comes from an explicit grad[1] if set, else a
// darker shade derived from the colour. Keeps event rendering backward-compatible.
function eventGrad(cat){
  if(!cat) return ["#A89878","#78684C"];
  const from=(cat.grad&&cat.grad[0])||cat.color||"#A89878";
  const to=(cat.grad&&cat.grad[1])||mixHex(from,"#000000",0.3);
  return [from,to];
}
// Shift category renders as a bold banded card (see EventCard) and carries an
// optional `end` time. It reuses the whole event pipeline (recurrence, calendar,
// occurrences) and is the foundation for future calendar sync.
const SHIFT_CAT = "Shift";
// v164 Build E · seed meal list for the shared meal planner. Each entry is just a name;
// planning a meal writes a Dinner-category event on the chosen date carrying this name.
const DEFAULT_MEALS = [
  "Spaghetti bolognese","Stir-fry & rice","Roast chicken","Tacos","Butter chicken",
  "Fish & chips","Homemade pizza","Beef stew","Pad thai","Leftovers","Takeaway",
];
// Day-off type palette (shift-category events with a dayOff type). Plain "off" and
// "custom" are 0h markers; "leave"/"sick" carry hours. Colours are mood-agnostic.
const OFF_COLOR="#4FB6A0", LEAVE_COLOR="#5B9BD8", SICK_COLOR="#E0885B";
// v248 · A PLAIN DAY OFF IS GREY. Mandy's call: teal made "nothing happening today" one of
// the loudest cards in the week. It now recedes and the working days carry the colour.
//
// A SEPARATE CONSTANT, NOT A CHANGE TO OFF_COLOR: `off` and `rdo` share OFF_COLOR, and v180
// records teal as Mandy's deliberate RDO pick. Repainting OFF_COLOR would have silently
// greyed RDO too. Only `off`/`custom` read DAYOFF_GREY; RDO keeps its teal.
//
// #6E7789 is NOT the swatch from the approved mockup (#5A627A). These colours are
// MOOD-AGNOSTIC - one hex over both a #0F1117 and a #FFFDF9 page - and the mockup grey
// measured 3.11:1 on Sleek, under the 4.5 floor, because the mockup only ever showed dark.
// Every mood-specific grey in the palette fails badly in the opposite mood (inkFaint 3.11
// on Sleek, inkMute bold 2.66 on Bold). #6E7789 is the only candidate clearing 4:1 in BOTH
// (4.19 Sleek / 4.43 Bold), and it is a shade lighter than approved for exactly that reason.
// Worst dE against anything it can share a week with: 29.3 vs Leave blue - well clear of 15.
const DAYOFF_GREY="#6E7789";
// v227 · TOIL is WINE #8E3B52, was violet #9B7CD8. Violet measured well (worst dE 27.0,
// vs him sapphire) but sat in the same purple family as WFH #7C9CD8. Wine clears every
// hue it can share a week with by dE 26.2 (worst: her magenta #BA2C73), and is the only
// candidate in a hue family NOTHING else in the work palette occupies.
// v180 · TOIL/WFH colours hoisted here (DAYOFF_META now references TOIL_COLOR, so it must
// exist first — module-scope const TDZ). The dead second amber is removed; the live amber
// is WORK_TOKENS.ot / OT_COLOR.
const TOIL_COLOR="#8E3B52", WFH_COLOR="#7C9CD8";
// v180 · DAYOFF_META and WORKEX_META now agree (same labels/colours) and both mirror
// WORK_TOKENS. `custom` keeps its own 0h "Day off work".
// v211 · CALENDAR TYPE COLOUR. DAYOFF_META gives `off` and `rdo` the SAME colour
// (OFF_COLOR), which is correct on a Work card — the leading icon distinguishes them
// there — but on the month grid there is no icon and they became one indistinguishable
// blob. RDO gets its own hue here, for the calendar only; the Work tab is untouched.
// v213 · WAS "#5B9BD8" — byte-identical to LEAVE_COLOR. v211 separated `rdo` from `off`
// and landed it exactly on top of Leave, so the blob was moved, not fixed.
//
// The first replacement proposed here was indigo #7C7CE0, which was only dE 10.3 from
// TOIL violet — a second collision, caught only because the candidates were MEASURED
// pairwise against EVERY other day-off hue rather than just the one they replaced.
// The mockup had not shown RDO and TOIL in the same week, so it could not have caught it.
//
// Lime clears all four by a wide margin (worst dE 50.5, vs off):
//   off #4FB6A0 teal · leave #5B9BD8 blue · sick #E0885B orange · toil #8E3B52 wine
// It is also the furthest of the candidates from the her/him person dots, which now sit
// in the same chip.
const CAL_RDO_COLOR="#8FBF4A";
function calDayOffColor(kind){
  if(kind==="rdo")   return CAL_RDO_COLOR;
  if(kind==="sick")  return SICK_COLOR;
  if(kind==="leave") return LEAVE_COLOR;
  if(kind==="toil")  return TOIL_COLOR;
  return DAYOFF_GREY;                     // off / custom — v248, grey like the Work card
}
// Compact glyph per day-off type for the month grid (Option A: icon + person dot).
function calDayOffIcon(kind){
  if(kind==="rdo")   return "M3 4h18v17H3z M3 9h18 M9 15l2 2 4-4";
  if(kind==="sick")  return "M3 8h18v12H3z M12 12v4 M10 14h4";
  if(kind==="leave") return "M3 18h18 M12 18V7 M12 7c-4 0-6 2-7 4h14c-1-2-3-4-7-4 M12 7V4";
  if(kind==="toil")  return "M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2";
  return "M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 8v4";
}

// CALENDAR-GRID LABEL *(v219)*. The month cell is ~72px wide, so "Day off work" wraps
// to two lines and makes the off chip the tallest thing on the grid. Mandy asked for a
// short form HERE ONLY — the Work tab, day sheet and edit sheet still read "Day off work",
// where there is room and the longer wording is clearer.
// A WRAPPER, not an edit to dayOffTitle or DAYOFF_META: both feed those other surfaces.
function calDayOffShort(ev){
  const t=dayOffTitle(ev);
  if(!ev||!ev.dayOff) return t;
  // `custom` carries a user-typed title; only fall back when it is empty, in which case
  // dayOffTitle already returned the long default.
  if(ev.dayOff==="custom") return t===DAYOFF_META.custom.label ? "Off" : t;
  if(ev.dayOff==="off")    return "Off";
  return t;                                  // leave / sick / toil / rdo already short
}

const DAYOFF_META={
  off:   {label:"Day off work",  color:DAYOFF_GREY, hours:false},
  leave: {label:"Leave",         color:LEAVE_COLOR, hours:true},
  sick:  {label:"Sick",          color:SICK_COLOR,  hours:true},
  toil:  {label:"TOIL",          color:TOIL_COLOR,  hours:true},
  rdo:   {label:"RDO",           color:OFF_COLOR,   hours:false},
  custom:{label:"Day off work",  color:DAYOFF_GREY, hours:false},
};
// ─── DAY-OFF TYPES *(v159, Build 2 — combined sheet)* ───────────────────────
// One combined "Day off" sheet covers six types, each stored as a standalone
// shift-category event tagged `workEx`, read by the resolver + shiftOccurrences:
//   off  → whole day not worked, 0h (dayOff set → suppressed for a regular person).
//   sick/leave/toil → REPLACE the day, re-houred (dayOffHours); dayOff set.
//   rdo  → REMOVES the day (0h); dayOff set.
//   ot   → ADDS hours (extra/weekend); NO dayOff (worked time); additive.
// (WFH is NOT here — it's a normal work day: a shift flag + a regular-pattern default.)
// `kind` drives the resolver: suppress (off/rdo), rehour (sick/leave/toil), add (ot).
const WORKEX_META={
  off:   {label:"Day off work",  color:DAYOFF_GREY,hours:false, dayOffFlag:true,  kind:"suppress"},
  sick:  {label:"Sick",     color:SICK_COLOR, hours:true,  dayOffFlag:true,  kind:"rehour"},
  leave: {label:"Leave",    color:LEAVE_COLOR,hours:true,  dayOffFlag:true,  kind:"rehour"},
  toil:  {label:"TOIL",     color:TOIL_COLOR, hours:true,  dayOffFlag:true,  kind:"rehour"},
  rdo:   {label:"RDO",      color:OFF_COLOR,  hours:false, dayOffFlag:true,  kind:"suppress"},
};
const WORKEX_ORDER=["off","sick","leave","toil","rdo"];

// ── v244 · WORK HISTORY ──────────────────────────────────────────────────────────────
// Until v244 an edit REPLACED the record: saveEvent overwrote in place and saveException
// rebuilt the row from scratch, so nothing anywhere remembered what a day used to be. A
// shift turned into TOIL left no trace that it had ever been a shift, and the hours it
// used to carry were simply gone.
//
// STORED SEPARATELY FROM THE EVENT, keyed by series id, for two reasons:
//   · Deleting and re-adding a day is a normal thing to do. History lives beside the
//     event so a rebuild does not erase the record of what came before it.
//   · saveException REPLACES the event object wholesale. Anything stored on the event
//     itself would be destroyed by the very operation we are trying to record.
//
// APPEND-ONLY, and never rewritten. An entry describes what was true at a moment; editing
// history to match the present would defeat the point of keeping it.
const WORK_HIST_KEY = "hb_workHist";
const WORK_HIST_MAX = 40;   // per series. A day edited 40 times has told its story.

// The TYPE of a work record, as one comparable token. `workEx` covers off/sick/leave/toil/
// rdo; anything else with a time is a shift. Returns null for a record that is neither, so
// a non-work event can never accidentally enter the log.
function workKind(ev){
  if(!ev) return null;
  if(ev.workEx && WORKEX_META[ev.workEx]) return ev.workEx;
  if(ev.dayOff && WORKEX_META[ev.dayOff]) return ev.dayOff;
  if(ev.category===SHIFT_CAT) return "shift";
  return null;
}

// Human label for a kind. Reads WORKEX_META so a renamed type stays consistent with the
// rest of the app - never a duplicated literal.
function workKindLabel(kind){
  if(kind==="shift") return "Shift";
  const m=WORKEX_META[kind];
  return m ? m.label : "Work";
}

// Compare two work records and describe what changed, in Mandy's terms rather than the
// code's. Returns [] when nothing meaningful moved, so a no-op save writes no entry - an
// edit sheet opened and closed must not litter the timeline.
function workDiff(before, after){
  const out=[];
  if(!before || !after) return out;
  const kb=workKind(before), ka=workKind(after);
  if(kb!==ka){
    // v245 · CARRY THE HOURS THAT ARE BEING DISCARDED.
    // The first version noted only "shift -> day off" and said, in a comment, that a type
    // change "already implies the times went with it". It does not: the times are the one
    // thing you actually lose, and the timeline read "Shift -> Day off" with no trace of
    // the 5:00-9:00 AM that used to be there. Mandy asked for exactly this.
    //
    // Attached to the KIND entry rather than emitted as a separate one, because it is not
    // an independent change - it is what the type change COST. `wasTime` is only set when
    // the outgoing record had a real span to lose.
    const entry={f:"kind", from:kb, to:ka};
    if(kb==="shift" && before.time && before.end){
      entry.wasTime=`${before.time}-${before.end}`;
      const h=shiftHours(before.time, before.end);
      if(h>0) entry.wasHours=h;
    } else if(kb!=="shift"){
      // The mirror case: a day off BECOMING a shift loses its recorded hours instead.
      const h=Number(before.dayOffHours)||0;
      if(h>0) entry.wasHours=h;
    }
    out.push(entry);
  }
  // Times as their own entry only while it IS a shift on both sides - otherwise the change
  // is already described by the kind entry above, carrying wasTime.
  if(kb==="shift" && ka==="shift"){
    if((before.time||"")!==(after.time||"") || (before.end||"")!==(after.end||""))
      out.push({f:"time", from:`${before.time||"?"}-${before.end||"?"}`, to:`${after.time||"?"}-${after.end||"?"}`});
    if((before.title||"")!==(after.title||""))
      out.push({f:"title", from:before.title||"", to:after.title||""});
  }
  const hb=Number(before.dayOffHours)||0, ha=Number(after.dayOffHours)||0;
  if(kb!=="shift" && ka!=="shift" && hb!==ha) out.push({f:"hours", from:hb, to:ha});
  if((before.assignee||"")!==(after.assignee||""))
    out.push({f:"who", from:before.assignee||"", to:after.assignee||""});
  return out;
}

// Display title for a day-off event. For the built-in "off" type we always show
// the current meta label (so older entries saved as "Day off" now read "Day off
// work"); "custom" keeps the user's typed title. Non-day-off events are unchanged.
function dayOffTitle(ev){
  if(!ev||!ev.dayOff) return ev?ev.title:"";
  if(ev.dayOff==="custom"){
    const t=(ev.title||"").trim();
    return t||DAYOFF_META.custom.label;
  }
  return (DAYOFF_META[ev.dayOff]||DAYOFF_META.off).label;
}
// ─── DAY-OFF ICON (traced from Mandy's clock+OFF glyph, v180) ───────────────
