// ─── LOCALSTORAGE HELPERS ────────────────────────────────────────────────────
function lsGet(key,fallback){try{const v=localStorage.getItem(key);return v!=null?JSON.parse(v):fallback;}catch{return fallback;}}
// THE SILENT KILLER: this used to be `catch{}` — a bare swallow. When localStorage hits
// its ~5MB quota, setItem THROWS, the write is lost, and the app carries on looking
// perfectly healthy while persisting NOTHING. Not just the photo that overflowed it:
// the next tick of a task, the next payment, the next point. All gone on reload, with
// no error and no clue why.
//
// A failed save must be LOUD. (Same rule as the v74 export bug: never report — or imply
// — a success you did not verify.) Subscribers get told, and the UI surfaces it.
let LS_FULL=false;
const lsListeners=new Set();
function onStorageFull(fn){ lsListeners.add(fn); return ()=>lsListeners.delete(fn); }
function lsSet(key,val){
  const ok=_lsSetOrig(key,val);
  if(ok&&key.startsWith("hb_")&&!APPEARANCE_KEYS.has(key.replace(/_[0-9a-f-]+$/,""))) sbPush(key,val);
  return ok;
}
// Roughly how much of the store is used. Every char of a UTF-16 string is ~2 bytes, but
// browsers vary; this is an INDICATOR, not an audit, and is labelled as one in the UI.
const LS_BUDGET = 5 * 1024 * 1024;
function lsUsage(){
  let n=0;
  try{
    for(let i=0;i<localStorage.length;i++){
      const k=localStorage.key(i);
      n += (k.length + (localStorage.getItem(k)||"").length) * 2;
    }
  }catch{}
  return n;
}

